    ["{name}: {reason}"] = "{name}: {reason}",
    ["Preparing {name}: waiting for the conversation service to connect…"] = "Preparando {name}: aguardando o serviço de conversa conectar…",
    ["Preparing {name}: waiting for the voice model to load…"] = "Preparando {name}: aguardando o modelo de voz carregar…",
    ["Preparing {name}: waiting for the conversation connection to open…"] = "Preparando {name}: aguardando a conexão de conversa abrir…",
    ["Preparing {name}: waiting for the game to place the character…"] = "Preparando {name}: aguardando o jogo posicionar o personagem…",
    ["Preparing {name}: waiting for the memory service…"] = "Preparando {name}: aguardando o serviço de memória…",
    ["Preparing {count} more companions…"] = "Preparando mais {count} companheiros…",
    ["The conversation service did not answer. Wait a moment, then invite again."] = "O serviço de conversa não respondeu. Aguarde um momento e convide novamente.",
    ["The voice model did not load. Check the voice in Settings or choose another one, then invite again."] = "O modelo de voz não carregou. Verifique a voz em Configurações ou escolha outra e convide novamente.",
    ["The memory service did not respond. Check your connection, then invite again."] = "O serviço de memória não respondeu. Verifique sua conexão e convide novamente.",
    ["The conversation connection did not open. Check your connection, then invite again."] = "A conexão de conversa não abriu. Verifique sua conexão e convide novamente.",
    ["Convai sign-in is busy right now. Wait a few minutes, then invite again."] = "O login do Convai está ocupado agora. Aguarde alguns minutos e convide novamente.",
    ["The Convai daily limit is used up. Choose another provider in Settings, or invite again tomorrow."] = "O limite diário do Convai foi atingido. Escolha outro provedor em Configurações ou convide novamente amanhã.",
    ["The Convai daily limit is used up. It resets at {time}. Choose another provider in Settings, or invite again then."] = "O limite diário do Convai foi atingido. Reinicia às {time}. Escolha outro provedor em Configurações ou convide novamente depois.",
    ["Calls are not available during combat."] = "As chamadas não estão disponíveis durante o combate.",
    ["Calls are not available right now."] = "As chamadas não estão disponíveis no momento.",
    ["Holocall ended: combat started."] = "Holochamada encerrada: o combate começou.",
    ["Holocall with {name} ended."] = "Holochamada com {name} encerrada.",
    ["Live picture unavailable. The call continues with the portrait."] = "Imagem ao vivo indisponível. A chamada continua com o retrato.",
    ["This contact cannot take a holocall."] = "Este contato não pode receber uma holochamada.",
    ["You are already on a call."] = "Você já está em uma chamada.",
    ["Ask a companion to drive to your selected map waypoint.\n\nGet into the passenger seat when they are ready."] = "Peça a um companheiro para dirigir até o ponto do mapa que você marcou.\n\nSente-se no banco do passageiro quando ele estiver pronto.",
    ["Auto: follows the completed encounter in this save.\n\nCasual: speaks with that familiarity.\n\nOrdinary: keeps her usual manner.\n\nIt does not imply an ongoing relationship."] = "Auto: segue o encontro concluído neste jogo salvo.\n\nInformal: fala com essa familiaridade.\n\nComum: mantém o jeito habitual dela.\n\nNão implica um relacionamento em andamento.",
    ["Auto: follows the relationship in this save.\n\nRomantic: speaks to V as a partner.\n\nOrdinary: keeps their usual manner.\n\nOnly changes how they talk, never your game choices."] = "Auto: segue o relacionamento neste jogo salvo.\n\nRomântico: fala com V como parceiro.\n\nComum: mantém o jeito habitual.\n\nMuda apenas a forma de falar, nunca as suas escolhas no jogo.",
    ["Bluetooth audio arrives a little late, so lips and subtitles can run ahead of the voice. This holds them back to match, for every voice.\n\nAuto: 150 ms while Windows plays through Bluetooth, none otherwise. Pick a value if your headset is faster or slower.\n\nThe game’s own dialogue has the same delay and does not correct it."] = "O áudio Bluetooth chega um pouco atrasado, então lábios e legendas podem ficar à frente da voz. Isto os atrasa para ficarem sincronizados, em todas as vozes.\n\nAuto: 150 ms com o Windows tocando pelo Bluetooth; sem atraso nos demais casos. Escolha um valor se o seu fone for mais rápido ou mais lento.\n\nO diálogo do próprio jogo tem o mesmo atraso e não o corrige.",
    ["Chat history stays available across game launches.\n\nForgetting a character also clears their saved Chat messages and drafts. Forgetting all memories clears all saved chats."] = "O histórico do Chat continua disponível entre as aberturas do jogo.\n\nEsquecer um personagem também apaga as mensagens salvas e os rascunhos do Chat dele. Esquecer todas as lembranças apaga todos os chats salvos.",
    ["Custom models are ones you added; they join the default choice by size."] = "Modelos personalizados são os que você adicionou; entram na escolha por tamanho.",
    ["Forget all memories applies to these characters.\n\nBrowsing the catalogue or inviting a companion does not add anyone to this count."] = "Esquecer todas as lembranças vale para estes personagens.\n\nNavegar pelo catálogo ou convidar um companheiro não adiciona ninguém a esta contagem.",
    ["Talk to story characters"] = "Conversar com personagens da história",
    ["{name} is busy right now."] = "{name} não pode falar agora.",
    ["{name} is not in your head right now."] = "{name} não está na sua cabeça agora.",
    ["{name} is a story character. Turn on Talk to story characters in Esc > Mods."] = "{name}: ative “Conversar com personagens da história” em Esc > Mods.",
    ["Talk to ordinary NPCs is off. Turn it on in Esc > Mods."] = "Conversar com NPCs comuns está desativado. Ative em Esc > Mods.",
    ["{name} is a child and cannot be talked to."] = "Não é possível conversar com {name}: é menor de idade.",
    ["{name} is not a person and cannot be talked to."] = "Não é possível conversar com {name}: não é uma pessoa.",
    ["{name} cannot be talked to: the mod cannot tell which voice fits."] = "Não é possível conversar com {name}: o mod não sabe qual voz usar.",
    ["If a character stops answering, voices stop or an error appears: choose Generate report and send the file it names to the developer, with a short note about what you were doing.\n\nThe logs listed below show what went wrong."] = "Se um personagem parar de responder, as vozes pararem ou aparecer um erro: escolha Gerar relatório e envie ao desenvolvedor o arquivo que ele indicar, com uma breve nota sobre o que você estava fazendo.\n\nOs registros listados abaixo mostram o que deu errado.",
    ["Invited characters are prepared immediately. Their memories start when you actually talk to them.\n\nOne player identity is shared across all saves and stays the same after forgetting.\n\nCurrent game context describes the world you have loaded."] = "Personagens convidados são preparados imediatamente. As lembranças deles começam quando você realmente fala com eles.\n\nUma identidade de jogador é compartilhada por todos os jogos salvos e permanece a mesma após esquecer.\n\nO contexto atual do jogo descreve o mundo que você carregou.",
    ["Only Mature models found. Turn on Mature content to use them."] = "Só modelos para adultos encontrados. Ative o Conteúdo adulto para usá-los.",
    ["Something on this PC (a firewall or security software) is blocking the connection to the model server you added."] = "Algo neste PC (um firewall ou software de segurança) está bloqueando a conexão com o servidor de modelo que você adicionou.",
    ["Never allowed: sex with minors or without consent, sex about real people, hate, real-world weapon or drug instructions. A safety check enforces the minors rule."] = "Proibido: sexo com menores ou sem consentimento, sexo com pessoas reais, ódio, instruções reais de armas ou drogas. Verificação aplica a regra dos menores.",
    ["Off: replies are text only and no voice is generated.\n\nWith Subtitles off as well, automatic reactions stay silent."] = "Desligado: as respostas são só texto e nenhuma voz é gerada.\n\nCom as Legendas também desligadas, as reações automáticas ficam em silêncio.",
    ["See what each character remembers and make one or all of them forget.\n\nMemories are kept across saves."] = "Veja o que cada personagem lembra e faça um ou todos esquecerem.\n\nAs lembranças são mantidas entre os jogos salvos.",
    ["Voxtral · not with Mature"] = "Voxtral · sem Conteúdo adulto",
    ["Voxtral is not used with Mature content."] = "O Voxtral não é usado com o Conteúdo adulto.",
    ["Needs Local AI or Custom."] = "Requer o Local AI ou o Personalizado.",
    ["Mature content is turned off because you chose a model that is not a Mature model."] = "O Conteúdo adulto foi desativado porque você escolheu um modelo que não é adulto.",
    ["Strong language, graphic violence, drugs and, between consenting adults, flirting and sex. Adults only (18+). Needs Local AI or Custom."] = "Linguagem forte, violência gráfica, drogas e, entre adultos que consentem, flerte e sexo. Só adultos (18+). Requer o Local AI ou o Personalizado.",
    ["Voxtral · Mistral cloud"] = "Voxtral · Nuvem Mistral",
    ["Voxtral · needs Mistral key"] = "Voxtral · requer chave Mistral",
    ["{name} (custom · too large)"] = "{name} (personalizado · muito grande)",
    ["{name} (custom, {size} GB, needs {need} GB)"] = "{name} (personalizado, {size} GB, precisa de {need} GB)",
    ["{name} (custom, {size} GB, too large for this card)"] = "{name} (personalizado, {size} GB, grande demais para esta placa)",
    ["Clear memories about you for every character you have talked to.\n\nYour player identity stays. A confirmation comes first."] = "Apaga as lembranças sobre você de todos os personagens com quem conversou.\n\nSua identidade de jogador é mantida. Antes, pede uma confirmação.",
    ["Saves a report file you can send to the developer.\n\nAPI keys, tokens, IDs, microphone audio and conversation text are left out. Without the conversation service, a shorter report is made from the files the game can read."] = "Salva um arquivo de relatório para enviar ao desenvolvedor.\n\nChaves de API, tokens, IDs, áudio do microfone e texto das conversas ficam de fora. Sem o serviço de conversa, é feito um relatório mais curto com os arquivos que o jogo pode ler.",
    ["The Mature pack’s uncensored models (for Local AI) give the full effect; standard models mostly refuse sex. Pack: installed."] = "Modelos sem censura do Mature pack (para o Local AI) dão efeito total; os padrão quase sempre recusam sexo. Pacote: instalado.",
    ["The Mature pack’s uncensored models (for Local AI) give the full effect; standard models mostly refuse sex. Pack: not installed (optional, on this mod’s Hugging Face page)."] = "Modelos sem censura do Mature pack (para o Local AI) dão efeito total; os padrão quase sempre recusam sexo. Pacote: não instalado (opcional, página do mod no Hugging Face).",
    ["Until you choose one, Local AI loads the largest model that fits your free graphics memory.\n\nOne model at a time; a change applies when it next loads. A model that is missing, too large or failing is replaced by the largest that fits, with one notice."] = "Até você escolher, o Local AI carrega o maior modelo que caiba na memória gráfica livre.\n\nUm modelo por vez; a mudança vale na próxima carga. Modelo ausente, grande demais ou com falha é trocado pelo maior que caiba, com um aviso.",
    ["Convai did not accept your API key. Check it in Settings > Conversation provider."] = "O Convai não aceitou sua chave de API. Verifique em Configurações > Provedor de conversa.",
    ["Local AI could not start. Check Local AI in Settings > Conversation provider."] = "O Local AI não pôde iniciar. Verifique o Local AI em Configurações > Provedor de conversa.",
    ["Mistral did not accept your key. Check it in Settings > Conversation provider."] = "O Mistral não aceitou sua chave. Verifique em Configurações > Provedor de conversa.",
    ["Mistral has no key yet, so Convai is used. Add your key in Settings > Conversation provider."] = "O Mistral ainda não tem chave, então o Convai é usado. Adicione sua chave em Configurações > Provedor de conversa.",
    ["Speaking to companions needs Convai for now. Set Conversation provider to Convai free tier in Settings > Conversation provider, or type your message."] = "Falar com os companheiros precisa do Convai por enquanto. Defina Provedor de conversa como Convai (plano gratuito) em Configurações > Provedor de conversa, ou digite sua mensagem.",
    ["Your Convai API key has reached its plan limit. Try again later or add a different key in Settings > Conversation provider."] = "Sua chave de API do Convai atingiu o limite do plano. Tente novamente mais tarde ou adicione outra chave em Configurações > Provedor de conversa.",
    ["Paste"] = "Colar",
    ["no Omni pack"] = "sem pacote OmniVoice",
    ["Add your Convai API key below to see and buy a plan."] = "Adicione sua chave de API do Convai abaixo para ver os planos e comprar um.",
    ["Add your Convai API key first."] = "Adicione primeiro sua chave de API do Convai.",
    ["Add your Convai API key first: copy it, then choose Paste on the Convai API key row."] = "Adicione primeiro sua chave de API do Convai: copie-a e depois escolha Colar na linha Chave de API do Convai.",
    ["Asking Convai for the payment page…"] = "Pedindo a página de pagamento ao Convai…",
    ["Asks Convai which plan your key has now. After paying, it can take about 15 seconds."] = "Pergunta ao Convai qual plano sua chave tem agora. Depois de pagar, pode levar cerca de 15 segundos.",
    ["Billed every month."] = "Cobrado todo mês.",
    ["Billed once a year."] = "Cobrado uma vez por ano.",
    ["Buy"] = "Comprar",
    ["Check"] = "Verificar",
    ["Check my plan"] = "Verificar meu plano",
    ["Checking your plan…"] = "Verificando seu plano…",
    ["Choose Check my plan to ask Convai."] = "Escolha Verificar meu plano para consultar o Convai.",
    ["Contacting Convai…"] = "Contatando o Convai…",
    ["Convai could not start the payment. Try again later."] = "O Convai não conseguiu iniciar o pagamento. Tente novamente mais tarde.",
    ["Convai did not accept your API key."] = "O Convai não aceitou sua chave de API.",
    ["Convai does not show a paid plan for your key yet."] = "O Convai ainda não mostra um plano pago para sua chave.",
    ["Convai has not confirmed your plan yet. Check it in Settings > Convai paid tier."] = "O Convai ainda não confirmou seu plano. Verifique em Configurações > Plano pago do Convai.",
    ["Convai paid tier"] = "Plano pago do Convai",
    ["Convai’s payment page is open in your browser. Your plan is active about 15 seconds after you pay."] = "A página de pagamento do Convai está aberta no seu navegador. Seu plano fica ativo cerca de 15 segundos depois que você pagar.",
    ["Convai’s payment service did not answer. Try again in a moment."] = "O serviço de pagamento do Convai não respondeu. Tente novamente em instantes.",
    ["Convai’s plans for this mod: more Convai conversations on your own Convai API key. Opens a page with the plans and their prices."] = "Planos do Convai para este mod: mais conversas do Convai com sua própria chave de API do Convai. Abre uma página com os planos e seus preços.",
    ["Conversations with Convai API key chosen as the provider use this plan."] = "As conversas com a chave de API do Convai escolhida como provedor usam este plano.",
    ["Get your Convai API key"] = "Obtenha sua chave de API do Convai",
    ["Manage or cancel plan"] = "Gerenciar ou cancelar plano",
    ["Free"] = "Grátis",
    ["Gamer, monthly"] = "Gamer, mensal",
    ["Gamer, yearly"] = "Gamer, anual",
    ["Gamer Pro, monthly"] = "Gamer Pro, mensal",
    ["Gamer Pro, yearly"] = "Gamer Pro, anual",
    ["Current plan"] = "Plano atual",
    ["This is your current plan. To change or cancel it, choose Manage or cancel plan below."] = "Este é o seu plano atual. Para alterá-lo ou cancelá-lo, escolha Gerenciar ou cancelar plano abaixo.",
    ["No key added"] = "Nenhuma chave adicionada",
    ["Not checked yet"] = "Ainda não verificado",
    ["Opened in your browser."] = "Aberto no seu navegador.",
    ["Opening the page in your browser…"] = "Abrindo a página no seu navegador…",
    ["Opens Convai’s payment page (Stripe) in your browser. You pay Convai directly; the mod never sees your card. Your plan is active about 15 seconds after you pay, and conversations then use your Convai API key."] = "Abre a página de pagamento do Convai (Stripe) no seu navegador. Você paga diretamente ao Convai; o mod nunca vê seu cartão. Seu plano fica ativo cerca de 15 segundos depois que você paga, e as conversas passam a usar sua chave de API do Convai.",
    ["Opens convai.com in your browser. Sign in or make a free account, copy your API key, then come back and choose Paste below."] = "Abre o convai.com no seu navegador. Entre ou crie uma conta gratuita, copie sua chave de API e depois volte e escolha Colar abaixo.",
    ["Opens your Convai billing page in your browser. Sign in with the same Convai account to change or cancel your plan."] = "Abre sua página de cobrança do Convai no seu navegador. Entre com a mesma conta do Convai para mudar ou cancelar seu plano.",
    ["Plans"] = "Planos",
    ["Plans Convai made for this mod. They give your own Convai API key more conversations; the free tier stays as it is."] = "Planos criados pelo Convai para este mod. Eles dão mais conversas à sua própria chave de API do Convai; o plano gratuito continua como está.",
    ["Prices in US dollars. You can cancel at any time on Convai’s billing page."] = "Preços em dólares americanos. Você pode cancelar a qualquer momento na página de cobrança do Convai.",
    ["The conversation service is not running, so plans cannot be shown. Restart the game."] = "O serviço de conversa não está em execução, então os planos não podem ser exibidos. Reinicie o jogo.",
    ["This key has no paid plan. Choose a plan below."] = "Esta chave não tem plano pago. Escolha um plano abaixo.",
    ["Your Convai plan"] = "Seu plano do Convai",
    ["Your Convai plan is active."] = "Seu plano do Convai está ativo.",
    ["Your Convai plan is active. Choose Convai API key in Settings > Conversation provider."] = "Seu plano do Convai está ativo. Escolha Chave de API do Convai em Configurações > Provedor de conversa.",
    ["Your Convai plan is active. Conversations now use your Convai API key."] = "Seu plano do Convai está ativo. As conversas agora usam sua chave de API do Convai.",
    ["Your browser could not be opened."] = "Não foi possível abrir seu navegador.",
    ["Your plan could not be read right now. Try again in a moment."] = "Não foi possível ler seu plano agora. Tente novamente em instantes.",
    ["{count} Convai interactions a month."] = "{count} interações do Convai por mês.",
    ["{plan}, {price} a month"] = "{plan}, {price} por mês",
    ["{plan}, {price} a year"] = "{plan}, {price} por ano",
    ["Sign in with Convai"] = "Entrar com o Convai",
    ["Sign in"] = "Entrar",
    ["Opens Convai’s sign-in page in your browser.\n\nSign in or make a free account, and your Convai API key is saved on this computer, the same as Paste. You have five minutes."] = "Abre a página de login do Convai no seu navegador.\n\nEntre ou crie uma conta gratuita, e sua chave de API do Convai será salva neste computador, do mesmo jeito que em Colar. Você tem cinco minutos.",
    ["Opening Convai’s sign-in page in your browser…"] = "Abrindo a página de login do Convai no seu navegador…",
    ["Sign in on the Convai page in your browser. Your key is saved here when you finish."] = "Entre na página do Convai no seu navegador. Sua chave será salva aqui quando você terminar.",
    ["Signed in. Your Convai API key is saved."] = "Sessão iniciada. Sua chave de API do Convai foi salva.",
    ["The sign-in took too long. Choose Sign in with Convai to try again."] = "O login demorou demais. Escolha Entrar com o Convai para tentar de novo.",
    ["The sign-in did not finish. Try again, or copy your key from convai.com and choose Paste."] = "O login não foi concluído. Tente de novo ou copie sua chave em convai.com e escolha Colar.",
    ["Choose one of the listed voices for V."] = "Escolha uma das vozes listadas para V.",
    ["Pocket · On your PC"] = "Pocket · No seu PC",
    ["Johnny in your head"] = "Johnny na sua cabeça",
    ["Johnny in your head is off. Turn it on in Settings > Conversations."] = "O Johnny na sua cabeça está desativado. Ative-o em Configurações > Conversas.",
    ["Choose how often Johnny speaks up."] = "Escolha com que frequência o Johnny se manifesta.",
    ["A display name is too long. Keep each one under {max} characters."] = "Um nome de exibição é longo demais. Mantenha cada um com menos de {max} caracteres.",
    ["A clip you add replaces the shipped voice of this character for Pocket, OmniVoice and the Voxtral cloud voice."] = "Um clipe que você adicionar substitui a voz original deste personagem para o Pocket, o OmniVoice e a voz em nuvem do Voxtral.",
    ["A new or removed clip counts from the next line this character speaks, once the current reply is over. Nothing needs restarting."] = "Um clipe novo ou removido vale a partir da próxima fala deste personagem, assim que a resposta atual terminar. Não é preciso reiniciar nada.",
    ["A record name can only use letters, digits, dots, dashes and underscores, for example Character.Rebecca."] = "Um nome de registro só pode usar letras, números, pontos, traços e sublinhados, por exemplo Character.Rebecca.",
    ["Add a display name"] = "Adicionar um nome de exibição",
    ["Add a record name"] = "Adicionar um nome de registro",
    ["Add a record name or a display name, so the game can find this character."] = "Adicione um nome de registro ou um nome de exibição, para que o jogo possa encontrar este personagem.",
    ["Add voice clip"] = "Adicionar clipe de voz",
    ["Another character of yours, {other}, already answers to this record or name."] = "Outro personagem seu, {other}, já responde a este registro ou nome.",
    ["Choose a gender"] = "Escolha um gênero",
    ["Choose a gender."] = "Escolha um gênero.",
    ["Chosen file: {name} ({size}). It is checked when you save it."] = "Arquivo escolhido: {name} ({size}). Ele é verificado quando você o salvar.",
    ["Chosen file: {name}, {seconds} seconds."] = "Arquivo escolhido: {name}, {seconds} segundos.",
    ["Clip removed."] = "Clipe removido.",
    ["Delete character"] = "Excluir personagem",
    ["Delete {name}? The character, its voice clip and what it remembers of you are removed."] = "Excluir {name}? O personagem, o clipe de voz e tudo o que ele lembra de você serão removidos.",
    ["Display names"] = "Nomes de exibição",
    ["Female"] = "Feminino",
    ["Filled in from the character you were facing: {name}."] = "Preenchido com o personagem para o qual você estava olhando: {name}.",
    ["For example: Character.Rebecca"] = "Por exemplo: Character.Rebecca",
    ["For example: Rebecca"] = "Por exemplo: Rebecca",
    ["Gender"] = "Gênero",
    ["Give the character a name."] = "Dê um nome ao personagem.",
    ["How the game finds this character"] = "Como o jogo encontra este personagem",
    ["It picks the voice when the character has no clip."] = "Quando o personagem não tem clipe, o gênero escolhe a voz.",
    ["Male"] = "Masculino",
    ["Memories"] = "Memórias",
    ["Name"] = "Nome",
    ["New character"] = "Novo personagem",
    ["No clip yet."] = "Ainda sem clipe.",
    ["Optional. Pocket, OmniVoice and the Voxtral cloud voice copy a clip you add. Without one the character speaks with a generic voice that fits the gender."] = "Opcional. O Pocket, o OmniVoice e a voz em nuvem do Voxtral copiam um clipe que você adicionar. Sem um clipe, o personagem fala com uma voz genérica que combina com o gênero.",
    ["Play saved clip"] = "Reproduzir clipe salvo",
    ["Record names"] = "Nomes de registro",
    ["Remove clip"] = "Remover clipe",
    ["Remove the voice clip? The character goes back to a generic voice."] = "Remover o clipe de voz? O personagem volta a ter uma voz genérica.",
    ["Remove the voice clip? {name} goes back to the shipped voice."] = "Remover o clipe de voz? {name} volta a usar a voz original.",
    ["Save clip"] = "Salvar clipe",
    ["Save the character first. Then it can have a voice clip, and it starts to remember your talks."] = "Salve o personagem primeiro. Depois ele poderá ter um clipe de voz e começará a lembrar das suas conversas.",
    ["Saved clip: {seconds} seconds."] = "Clipe salvo: {seconds} segundos.",
    ["Saved. The clip is a little long: 10 to 18 seconds copies best."] = "Salvo. O clipe está um pouco longo: de 10 a 18 segundos é o que copia melhor.",
    ["Saved. The clip is a little short: 10 to 18 seconds copies best."] = "Salvo. O clipe está um pouco curto: de 10 a 18 segundos é o que copia melhor.",
    ["That file is not a recording the voices can read. Use a WAV, MP3, OGG or FLAC file."] = "Este arquivo não é uma gravação que as vozes possam ler. Use um arquivo WAV, MP3, OGG ou FLAC.",
    ["That file is too big for a voice clip."] = "Este arquivo é grande demais para um clipe de voz.",
    ["The clip is mostly silence. Use a clip where somebody is talking most of the time."] = "O clipe é quase todo silêncio. Use um clipe em que alguém fale a maior parte do tempo.",
    ["The clip is too long. Use at most {max} seconds."] = "O clipe é longo demais. Use no máximo {max} segundos.",
    ["The clip is too short. Use at least {min} seconds."] = "O clipe é curto demais. Use pelo menos {min} segundos.",
    ["The game did not name anyone. Face the character, then choose Settings > Edit characters > Open in the game again."] = "O jogo não identificou ninguém. Fique de frente para o personagem e escolha Configurações > Editar personagens > Abrir, no jogo, de novo.",
    ["The game recognises the person you talk to by a record name, a display name, or both. A record name looks like Character.Rebecca or NCA.Rebecca. Add at least one."] = "O jogo reconhece a pessoa com quem você conversa por um nome de registro, um nome de exibição ou os dois. Um nome de registro tem a forma de Character.Rebecca ou NCA.Rebecca. Adicione pelo menos um.",
    ["The name is too long. Keep it under {max} characters."] = "O nome é longo demais. Mantenha-o com menos de {max} caracteres.",
    ["The name of the character’s record in the game files."] = "O nome do registro do personagem nos arquivos do jogo.",
    ["The name the character goes by. They give it when somebody asks who they are."] = "O nome pelo qual o personagem é conhecido. Ele o diz quando alguém pergunta quem ele é.",
    ["The name the game shows for the character."] = "O nome que o jogo mostra para o personagem.",
    ["The recording is distorted. Record it again, a little quieter."] = "A gravação está distorcida. Grave de novo, um pouco mais baixo.",
    ["The recording is too low in quality. Use at least {min} Hz."] = "A qualidade da gravação está baixa demais. Use pelo menos {min} Hz.",
    ["The recording is too quiet to copy. Record it louder, or closer to the microphone."] = "A gravação está baixa demais para ser copiada. Grave mais alto ou mais perto do microfone.",
    ["The saved clip could not be loaded."] = "Não foi possível carregar o clipe salvo.",
    ["The words said in the clip are too long. Keep them under {max} characters."] = "As palavras ditas no clipe são longas demais. Mantenha-as com menos de {max} caracteres.",
    ["This character speaks with a generic voice that fits the gender."] = "Este personagem fala com uma voz genérica que combina com o gênero.",
    ["This character speaks with the shipped voice."] = "Este personagem fala com a voz original.",
    ["This computer cannot convert that file. Save it as a WAV and try again."] = "Este computador não consegue converter esse arquivo. Salve-o como WAV e tente novamente.",
    ["Too many display names. Keep {max} or fewer."] = "Nomes de exibição demais. Mantenha {max} ou menos.",
    ["Too many record names. Keep {max} or fewer."] = "Nomes de registro demais. Mantenha {max} ou menos.",
    ["Type the words said in the clip, at least {min} characters."] = "Digite as palavras ditas no clipe, com pelo menos {min} caracteres.",
    ["Type what the clip says, as spoken. OmniVoice needs it to copy the voice."] = "Digite o que o clipe diz, do jeito que foi falado. O OmniVoice precisa disso para copiar a voz.",
    ["Use the character I’m facing"] = "Usar o personagem para o qual estou olhando",
    ["Use {min} to {max} seconds of one person speaking clearly, with no music or other voices. {goodMin} to {goodMax} seconds copies best. WAV, MP3, OGG or FLAC."] = "Use de {min} a {max} segundos de uma só pessoa falando com clareza, sem música nem outras vozes. De {goodMin} a {goodMax} segundos é o que copia melhor. WAV, MP3, OGG ou FLAC.",
    ["Voice"] = "Voz",
    ["You have as many voice clips as the editor keeps ({max}). Remove one first."] = "Você já tem tantos clipes de voz quantos o editor guarda ({max}). Remova um antes.",
    ["Who this character is, what they know and how they look. Writing it as “I am …” works best. A long bio makes replies slower, so keep it tight."] = "Quem é este personagem, o que ele sabe e como ele é. Escrever como “Eu sou …” funciona melhor. Uma biografia longa deixa as respostas mais lentas, então seja breve.",
    ["Words said in the clip"] = "Palavras ditas no clipe",
    ["You have made as many characters as the editor keeps ({max}). Delete one first."] = "Você já criou o máximo de personagens que o editor guarda ({max}). Exclua um primeiro.",
    ["Your character"] = "Seu personagem",
    ["Your characters"] = "Seus personagens",
    ["{other} already has a profile in the mod, and that profile always wins. Use another record or name."] = "{other} já tem um perfil no mod, e esse perfil sempre prevalece. Use outro registro ou nome.",
    ["A pack is one folder too deep. See Help in Settings."] = "Pacote com uma pasta a mais. Veja Ajuda em Configurações.",
    ["All files found."] = "Todos os arquivos encontrados.",
    ["Browser"] = "Navegador",
    ["Found."] = "Encontrado.",
    ["Found: {list}."] = "Encontrado: {list}.",
    ["Game version"] = "Versão do jogo",
    ["Graphics card"] = "Placa de vídeo",
    ["Internet"] = "Internet",
    ["Loaded."] = "Carregado.",
    ["Local AI could not start. Generate a report below and send it, or choose another conversation provider."] = "O Local AI não pôde iniciar. Gere um relatório abaixo e envie, ou escolha outro provedor de conversa.",
    ["Local AI found no graphics card it can use. It needs an NVIDIA or AMD card with a current driver. Update the driver, or choose another conversation provider."] = "O Local AI não encontrou uma placa de vídeo que possa usar. Ele precisa de uma placa NVIDIA ou AMD com driver atualizado. Atualize o driver ou escolha outro provedor de conversa.",
    ["Missing: {files}. Extract the Scripts zip into the Cyberpunk 2077 folder again and let it replace the files."] = "Ausentes: {files}. Extraia o zip Scripts de novo na pasta do Cyberpunk 2077 e deixe que ele substitua os arquivos.",
    ["Mod files"] = "Arquivos do mod",
    ["Mod manager"] = "Gerenciador de mods",
    ["Moved into place from {folder}: {packs}."] = "Movidos de {folder}: {packs}.",
    ["No Local AI pack found. Download one from the mod’s Hugging Face page and extract it into the Cyberpunk 2077 folder, or choose another conversation provider."] = "Nenhum pacote do Local AI encontrado. Baixe um na página do mod no Hugging Face e extraia na pasta do Cyberpunk 2077, ou escolha outro provedor de conversa.",
    ["No problem found. Select a line to see what was checked."] = "Nenhum problema encontrado. Selecione uma linha para ver o que foi verificado.",
    ["No sign of the conversation service in this session: the Runtime is missing or did not load. Extract the full install zip (AI-NPC-LLM-Companions) straight into the Cyberpunk 2077 folder (not into a new folder), check that red4ext/plugins/AiNpcCyberpunkMod is there, then restart the game. The full install is on the mod’s Nexus Mods page."] = "Nenhum sinal do serviço de conversa nesta sessão: o Runtime está ausente ou não carregou. Extraia o zip de instalação completo (AI-NPC-LLM-Companions) diretamente na pasta do Cyberpunk 2077 (não em uma pasta nova), confira se red4ext/plugins/AiNpcCyberpunkMod está lá e reinicie o jogo. A instalação completa está na página do mod no Nexus Mods.",
    ["None found: installed by hand."] = "Nenhum encontrado: instalado manualmente.",
    ["None installed. They are optional."] = "Nenhum instalado. São opcionais.",
    ["Not needed: Local AI and the voice run on this PC."] = "Não é necessário: o Local AI e a voz rodam neste PC.",
    ["Not used"] = "Não usado",
    ["Not your conversation provider. Choose it in Settings > Conversation provider."] = "Não é o seu provedor de conversa. Escolha-o em Configurações > Provedor de conversa.",
    ["Note"] = "Nota",
    ["OK"] = "OK",
    ["Optional packs"] = "Pacotes opcionais",
    ["Problem"] = "Problema",
    ["Problems found: {count}. Select a line marked Problem to read what to do."] = "Problemas encontrados: {count}. Selecione uma linha marcada como Problema para ler o que fazer.",
    ["RED4ext is not loaded. Install it from Nexus Mods, then restart the game. It also starts the conversation service."] = "O RED4ext não foi carregado. Instale-o pelo Nexus Mods e reinicie o jogo. Ele também inicia o serviço de conversa.",
    ["Reached {host}."] = "Conectado a {host}.",
    ["Scripts and Runtime"] = "Scripts e Runtime",
    ["Scripts {scripts} and Runtime {runtime}."] = "Scripts {scripts} e Runtime {runtime}.",
    ["Scripts {scripts} on Runtime base {runtime}."] = "Scripts {scripts} sobre a base do Runtime {runtime}.",
    ["These Scripts {scripts} need the Runtime base {required} or newer, and your Runtime is {runtime}. Extract the full install zip (AI-NPC-LLM-Companions, on Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Estes Scripts {scripts} precisam da base do Runtime {required} ou mais recente, e o seu Runtime é {runtime}. Extraia o zip de instalação completo (AI-NPC-LLM-Companions, no Nexus Mods) na pasta do Cyberpunk 2077 e depois reinicie o jogo.",
    ["The Runtime is older than {required}. Get the full install zip."] = "O Runtime é mais antigo que {required}. Baixe o zip completo.",
    ["Setup check"] = "Verificação de instalação",
    ["Some mod files are missing. Extract the update zip again. See Help in Settings."] = "Faltam arquivos do mod. Extraia de novo o Update-ZIP. Veja Ajuda em Configurações.",
    ["Some pack files could not be moved into place because different files are already there. Extract the pack into the Cyberpunk 2077 folder again and let it replace the files."] = "Alguns arquivos do pacote não puderam ser movidos porque outros arquivos diferentes já estão lá. Extraia o pacote de novo na pasta do Cyberpunk 2077 e deixe que ele substitua os arquivos.",
    ["The Runtime is incomplete ({code}). Extract the full install zip (AI-NPC-LLM-Companions) into the Cyberpunk 2077 folder again and let it replace the files, then restart the game."] = "O Runtime está incompleto ({code}). Extraia de novo o zip de instalação completo (AI-NPC-LLM-Companions) na pasta do Cyberpunk 2077 e deixe substituir os arquivos; depois reinicie o jogo.",
    ["Mod Organizer 2 does not show a file of the Runtime to the program. Close the game and Mod Organizer 2, extract the full install zip (AI-NPC-LLM-Companions) into the Cyberpunk 2077 folder by hand, then start the game."] = "O Mod Organizer 2 não mostra um arquivo do Runtime para o programa. Feche o jogo e o Mod Organizer 2, extraia manualmente o zip de instalação completo (AI-NPC-LLM-Companions) na pasta do Cyberpunk 2077 e depois inicie o jogo.",
    ["The settings file of the launcher, launcher.ini, is missing from red4ext/plugins/AiNpcCyberpunkMod, so the game cannot start the conversation service. Extract the full install zip (AI-NPC-LLM-Companions) straight into the Cyberpunk 2077 folder again (by hand, also with Vortex) and let it replace the files, then restart the game."] = "O arquivo de configurações do iniciador, launcher.ini, não está em red4ext/plugins/AiNpcCyberpunkMod, então o jogo não consegue iniciar o serviço de conversa. Extraia de novo o zip de instalação completo (AI-NPC-LLM-Companions) direto na pasta do Cyberpunk 2077 (à mão, mesmo com o Vortex) e deixe substituir os arquivos; depois reinicie o jogo.",
    ["The conversation service cannot reach the internet. See Help in Settings."] = "O serviço de conversa não consegue acessar a internet. Veja Ajuda em Configurações.",
    ["The conversation service cannot reach {host}. Allow Node.js through your firewall or antivirus (Windows asks once; choose Allow), check your internet, then restart the game."] = "O serviço de conversa não consegue acessar {host}. Permita o Node.js no firewall ou antivírus (o Windows pergunta uma vez; escolha Permitir acesso), verifique sua internet e reinicie o jogo.",
    ["The conversation service could not start ({code}). Restart the game. If it happens again, generate a report below and send it."] = "O serviço de conversa não pôde iniciar ({code}). Reinicie o jogo. Se acontecer de novo, gere um relatório abaixo e envie.",
    ["The conversation service did not start. Is the Runtime installed? See Help in Settings."] = "O serviço de conversa não iniciou. O Runtime está instalado? Veja Ajuda em Configurações.",
    ["The game version could not be read."] = "Não foi possível ler a versão do jogo.",
    ["This PC cannot look up {host}. Check your internet connection, then restart the game."] = "Este PC não consegue resolver {host}. Verifique sua conexão com a internet e reinicie o jogo.",
    ["Open r6/logs/redscript_rCURRENT.log. A mod it names is why the scripts did not load."] = "Abra r6/logs/redscript_rCURRENT.log. Um mod citado ali impede os scripts de carregar.",
    ["This mod’s scripts did not load. Open r6/logs/redscript_rCURRENT.log. If the error names another mod, that mod is the problem. Missing or old Codeware or redscript, or a game version other than {game}, can also cause it."] = "Os scripts deste mod não carregaram. Abra r6/logs/redscript_rCURRENT.log. Se o erro citar outro mod, esse mod é o problema. Codeware ou redscript ausente ou antigo, ou uma versão do jogo diferente de {game}, também pode causar isso.",
    ["Missing: {names}. Install them and restart the game."] = "Faltam: {names}. Instale-os e reinicie o jogo.",
    ["Install or update: {names}. Then restart the game."] = "Instale ou atualize: {names}. Depois reinicie o jogo.",
    ["Codeware is too old. Update it from Nexus Mods, then restart the game."] = "O Codeware está desatualizado. Atualize pelo Nexus Mods e reinicie o jogo.",
    ["Version {version}."] = "Versão {version}.",
    ["Version {version}. The mod is tested on {game} only, so some things may not work."] = "Versão {version}. O mod foi testado apenas na {game}, então algumas coisas podem não funcionar.",
    ["Version {version}. These files are the mod build for game {build}. Extract the full install zip made for game {game}, from the mod’s Nexus Mods page, into the Cyberpunk 2077 folder, then restart the game."] = "Versão {version}. Estes arquivos são o build do mod para o jogo {build}. Extraia na pasta do Cyberpunk 2077 o zip de instalação completo feito para o jogo {game}, da página do mod no Nexus Mods, e depois reinicie o jogo.",
    ["Vortex. Install the optional packs by hand into the Cyberpunk 2077 folder, as the install steps say. Install the full install zip as one mod and update that mod with each new full install zip."] = "Vortex. Instale manualmente os pacotes opcionais na pasta do Cyberpunk 2077, como dizem os passos de instalação. Instale o zip de instalação completo como um mod e atualize esse mod com cada novo zip de instalação completo.",
    ["{name} is missing. Install it from Nexus Mods, then restart the game."] = "Falta {name}. Instale pelo Nexus Mods e reinicie o jogo.",
    ["{name}, {memory} GB of video memory."] = "{name}, {memory} GB de memória de vídeo.",
    ["{packs} is one folder too deep, in {folder}. Restart the game and the mod moves it into place. If it is still there afterwards, move the red4ext folder inside it into the Cyberpunk 2077 folder."] = "{packs} tem uma pasta a mais, dentro de {folder}. Reinicie o jogo e o mod o move para o lugar certo. Se ainda estiver lá depois, mova a pasta red4ext que está dentro dele para a pasta do Cyberpunk 2077.",
    ["Add an endpoint URL and a model ID first."] = "Adicione primeiro a URL do endpoint e o ID do modelo.",
    ["Convai: the custom provider is not set up yet"] = "Convai: provedor personalizado ainda não configurado",
    ["Copy the base URL from your provider, for example https://openrouter.ai/api/v1, https://nano-gpt.com/api/v1 or http://localhost:11434/v1 (Ollama). It is read from the clipboard once and saved on this computer.\n\nOnly this computer and your home network may use http://. You can also fill in endpoint=, model= and api-key= in player-custom-endpoint.txt in the conversation service folder.\n\nNothing is sent until you choose this provider or press Test connection."] = "Copie a URL base do seu provedor, por exemplo https://openrouter.ai/api/v1, https://nano-gpt.com/api/v1 ou http://localhost:11434/v1 (Ollama). Ela é lida da área de transferência uma única vez e salva apenas neste computador.\n\nSomente este computador e a sua rede doméstica podem usar http://. Você também pode preencher endpoint=, model= e api-key= em player-custom-endpoint.txt, na pasta do serviço de conversa.\n\nNada é enviado até você escolher este provedor ou pressionar Testar conexão.",
    ["Copy the model ID from your provider first, for example meta-llama/llama-3.1-8b-instruct on OpenRouter or llama3.2 on Ollama. It is read from the clipboard once and saved on this computer."] = "Primeiro copie o ID do modelo do seu provedor, por exemplo meta-llama/llama-3.1-8b-instruct no OpenRouter ou llama3.2 no Ollama. Ele é lido da área de transferência uma única vez e salvo apenas neste computador.",
    ["Copy your API key from your provider first. It is read from the clipboard once and saved on this computer only. A server on your own computer, such as Ollama or LM Studio, usually needs no key."] = "Primeiro copie sua chave de API do seu provedor. Ela é lida da área de transferência uma única vez e salva apenas neste computador. Um servidor no seu próprio computador, como Ollama ou LM Studio, geralmente não precisa de chave.",
    ["Custom (OpenAI-compatible)"] = "Personalizado (API OpenAI)",
    ["Custom API key"] = "Chave de API própria",
    ["Custom endpoint URL"] = "URL do endpoint próprio",
    ["Custom model ID"] = "ID do modelo próprio",
    ["Custom provider replies are spoken by a local voice instead of the Convai cloud voice."] = "Respostas do provedor personalizado: voz local, não a voz em nuvem do Convai.",
    ["Custom: key not accepted"] = "Personalizado: chave não aceita",
    ["Custom: model unavailable"] = "Personalizado: modelo indisponível",
    ["Custom: out of credits"] = "Personalizado: sem créditos",
    ["Custom: rate limited for now"] = "Personalizado: limite atingido por ora",
    ["Deletes the saved endpoint URL. The custom provider needs one to answer."] = "Apaga a URL do endpoint salva. O provedor personalizado precisa dela para responder.",
    ["Deletes the saved key. Replies from the custom provider are then asked for without a key."] = "Apaga a chave salva. Depois, as respostas do provedor personalizado são pedidas sem chave.",
    ["Deletes the saved model ID. The custom provider needs one to answer."] = "Apaga o ID do modelo salvo. O provedor personalizado precisa dele para responder.",
    ["Failed"] = "Falhou",
    ["It answered in {ms} ms."] = "Respondeu em {ms} ms.",
    ["It could not be saved."] = "Não foi possível salvar.",
    ["Model ID: {model}"] = "ID do modelo: {model}",
    ["Only https:// works outside this computer and your home network."] = "Só https:// funciona fora deste computador e da sua rede doméstica.",
    ["Paste API key"] = "Colar chave de API",
    ["Paste endpoint URL"] = "Colar URL",
    ["Paste model ID"] = "Colar ID do modelo",
    ["Sends one tiny message to your endpoint with the saved model ID and key, and shows how it answered. It uses next to nothing of your credits."] = "Envia uma mensagem minúscula ao seu endpoint com o ID do modelo e a chave salvos, e mostra como ele respondeu. Gasta praticamente nada dos seus créditos.",
    ["Test"] = "Testar",
    ["Test connection"] = "Testar conexão",
    ["Testing the connection…"] = "Testando a conexão…",
    ["Testing…"] = "Testando…",
    ["That is too long."] = "Está longo demais.",
    ["That was not accepted."] = "Isso não foi aceito.",
    ["The account is out of credits. Add credits with your provider."] = "A conta está sem créditos. Adicione créditos no seu provedor.",
    ["The address must start with https:// or http://."] = "O endereço deve começar com https:// ou http://.",
    ["The address sends you somewhere else. Use the final address from your provider."] = "O endereço redireciona para outro lugar. Use o endereço final do seu provedor.",
    ["That address is a web page, not the API. For OpenRouter use https://openrouter.ai/api/v1."] = "Este endereço é uma página da web, não a API. Para o OpenRouter, use https://openrouter.ai/api/v1.",
    ["That address is a web page, not the API. Use the API address from your provider."] = "Este endereço é uma página da web, não a API. Use o endereço da API fornecido pelo seu provedor.",
    ["A model ID is a short name like that, not a web address."] = "Um ID de modelo é um nome curto como esse, não um endereço da web.",
    ["The clipboard does not hold a model ID."] = "A área de transferência não tem um ID de modelo.",
    ["The clipboard does not hold a web address."] = "A área de transferência não tem um endereço web.",
    ["The clipboard does not hold an API key."] = "A área de transferência não tem uma chave de API.",
    ["The clipboard is empty. Copy it first."] = "A área de transferência está vazia. Copie antes.",
    ["The connection test failed."] = "O teste de conexão falhou.",
    ["The connection works. The endpoint accepted your model and key."] = "A conexão funciona. O endpoint aceitou seu modelo e sua chave.",
    ["The conversation service is not running, so nothing can be tested. Restart the game."] = "O serviço de conversa não está em execução, então nada pode ser testado. Reinicie o jogo.",
    ["The custom provider did not accept your key. Check it in Settings > Conversation provider."] = "Provedor personalizado recusou a chave. Confira em Configurações > Provedor de conversa.",
    ["The custom provider did not answer. Check its address in Settings, or try again."] = "Provedor personalizado não respondeu. Confira o endereço em Configurações ou tente de novo.",
    ["The custom provider does not know that model ID. Check it in Settings."] = "Provedor personalizado não conhece este ID de modelo. Confira em Configurações.",
    ["The custom provider is not set up, so Convai is used. Add its URL and model ID in Settings."] = "Sem provedor personalizado: usa o Convai. Adicione URL e ID do modelo em Configurações.",
    ["The custom provider is rate limiting you. Try again in a moment."] = "O provedor personalizado limitou seu uso. Tente de novo em instantes.",
    ["The custom provider says your account is out of credits. Add credits there, then try again."] = "Sem créditos na conta do provedor personalizado. Adicione lá e tente de novo.",
    ["The endpoint URL was removed."] = "A URL do endpoint foi removida.",
    ["The endpoint answered with no text. Check the model ID."] = "O endpoint respondeu sem texto. Verifique o ID do modelo.",
    ["The endpoint did not accept your API key."] = "O endpoint não aceitou sua chave de API.",
    ["The endpoint did not answer. Check its address."] = "O endpoint não respondeu. Verifique o endereço.",
    ["The endpoint does not know that model ID."] = "O endpoint não conhece este ID de modelo.",
    ["The endpoint is rate limiting you. Try again in a moment."] = "O endpoint está limitando seu uso. Tente de novo em instantes.",
    ["The endpoint is rate limiting you. Wait about {seconds} seconds, then try again."] = "O endpoint está limitando seu uso. Aguarde cerca de {seconds} segundos e tente de novo.",
    ["The endpoint refused the request. Check the model ID and the address."] = "O endpoint recusou a solicitação. Verifique o ID do modelo e o endereço.",
    ["The endpoint reported an error on its side. Try again in a moment."] = "O endpoint informou um erro do lado dele. Tente de novo em instantes.",
    ["The endpoint took too long to answer."] = "O endpoint demorou demais para responder.",
    ["The model ID was removed."] = "O ID do modelo foi removido.",
    ["The provider said: {detail}"] = "O provedor disse: {detail}",
    ["This address is not encrypted, which is fine on your own computer or home network."] = "Este endereço não é criptografado, o que é aceitável no seu computador ou rede doméstica.",
    ["Use the base URL only: no password, query or #."] = "Use somente a URL base: sem senha, consulta ou #.",
    ["Waiting for the endpoint to answer…"] = "Aguardando o endpoint responder…",
    ["Custom: free daily limit reached"] = "Personalizado: limite diário gratuito atingido",
    ["New address saved. Paste your API key again for it."] = "Novo endereço salvo. Cole a chave de API novamente.",
    ["The free daily limit for this model was reached. It resets at {time}."] = "Limite diário gratuito deste modelo atingido. Reinicia às {time}.",
    ["The free daily limit for this model was reached. Try again after it resets."] = "Limite diário gratuito deste modelo atingido. Tente de novo após a renovação.",
    ["This model spends its reply on thinking. Choose a non-reasoning model in Settings."] = "Este modelo gasta a resposta pensando. Escolha um modelo sem raciocínio em Configurações.",
    ["All"] = "Todos",
    ["Also changed: {names}."] = "Também alterado: {names}.",
    ["Choose any character from the list below. They do not need to be in your current party."] = "Escolha qualquer personagem da lista abaixo. Ele não precisa estar no seu grupo atual.",
    ["Defaults restored."] = "Padrões restaurados.",
    ["Drag the slider, or press left and right, to turn the page."] = "Arraste o controle deslizante ou use as setas esquerda e direita para mudar de página.",
    ["How loud the companions’ and characters’ voices are. 100 is the normal level, 150 the default.\n\nAbove 100 the voices get louder, with a limiter so they do not crackle. V’s voice has its own setting below, and the game’s own dialogue and sounds do not change.\n\nThe next reply uses it."] = "O volume das vozes dos companheiros e dos personagens. 100 é o nível normal e 150 o padrão.\n\nAcima de 100 as vozes ficam mais altas, com um limitador para não estourar. A voz do V tem um ajuste próprio abaixo, e os diálogos e sons do próprio jogo não mudam.\n\nA próxima resposta usa o valor.",
    ["How loud V’s own voice is, for V’s typed and microphone lines. 100 is the normal level, 150 the default.\n\nAbove 100 the voice gets louder, with a limiter so it does not crackle. The companions’ voices and the game’s own dialogue and sounds do not change.\n\nThe next line uses it."] = "O volume da própria voz do V, nas falas digitadas e nas ditas pelo microfone. 100 é o nível normal e 150 o padrão.\n\nAcima de 100 a voz fica mais alta, com um limitador para não estourar. As vozes dos companheiros e os diálogos e sons do próprio jogo não mudam.\n\nA próxima fala usa o valor.",
    ["Not available right now."] = "Não disponível no momento.",
    ["Open Settings to restore its defaults."] = "Abra Configurações para restaurar os padrões.",
    ["Page"] = "Página",
    ["Show only the models whose name starts with this letter."] = "Mostra apenas os modelos cujo nome começa com esta letra.",
    ["Starts with"] = "Começa com",
    ["Open AI NPC Cyberpunk Mod in the Mods list."] = "Abra o AI NPC Cyberpunk Mod na lista de Mods.",
    ["The settings could not be saved. Nothing was changed."] = "Não foi possível salvar as configurações. Nada foi alterado.",
    ["Send error reports automatically"] = "Enviar relatórios de erro automaticamente",
    ["Error reports go to the developer. Turn them off in Settings > Privacy and help."] = "Relatórios de erro enviados automaticamente. Desative: Configurações > Privacidade e ajuda.",
    ["The Companion Manager needs Mod Configuration Menu 0.10.5 or newer, or Native Settings UI"] = "O Gerenciador de companheiros precisa do Mod Configuration Menu 0.10.5+ ou Native Settings UI",
    ["Update Mod Configuration Menu to 0.10.5 or newer, or install Native Settings UI"] = "Atualize o Mod Configuration Menu para 0.10.5+ ou instale o Native Settings UI",
    ["Stand up to open the Companion Manager"] = "Levante-se para abrir o Gerenciador de companheiros",
    ["The Companion Manager needs Mod Configuration Menu 0.10.5 or newer, or Native Settings UI {nsui} or newer. Either one is enough. Install one from Nexus Mods, then restart the game."] = "O Gerenciador de companheiros precisa do Mod Configuration Menu 0.10.5 ou mais novo, ou do Native Settings UI {nsui} ou mais novo. Qualquer um dos dois basta. Instale um deles pelo Nexus Mods e reinicie o jogo.",
    ["Mod Configuration Menu is too old. Update it to 0.10.5 or newer, or install Native Settings UI, then restart the game."] = "O Mod Configuration Menu está desatualizado. Atualize para a versão 0.10.5 ou mais nova, ou instale o Native Settings UI, e reinicie o jogo.",
    ["Previous page"] = "Página anterior",
    ["Next page"] = "Próxima página",
    ["Starts with: {letter}"] = "Começa com: {letter}",
    ["Characters and party"] = "Personagens e grupo",
    ["Load a save first"] = "Carregue um jogo",
    ["Inviting characters and managing your party need a loaded game."] = "Convidar personagens e gerenciar seu grupo exige um jogo carregado.",
    ["Voxtral (recommended)"] = "Voxtral (recomendado)",
    ["Defaults"] = "Padrões",
    ["Press Confirm to put every setting back to its default."] = "Pressione Confirmar para devolver cada configuração ao padrão.",
    ["Local AI stopped working and was restarted."] = "O Local AI parou de funcionar e foi reiniciado.",
    ["Local AI runs mostly on your processor here, so replies will be slow."] = "O Local AI roda quase todo no seu processador, então as respostas serão lentas.",
    ["Local AI is back on your graphics card, so replies are faster again."] = "O Local AI voltou para a sua placa de vídeo, então as respostas ficaram mais rápidas de novo.",
    ["Voice files"] = "Arquivos de voz",
    ["The voice files are incomplete. Reinstall the Full download from Nexus Mods."] = "Os arquivos de voz estão incompletos. Reinstale o zip de instalação completo do Nexus Mods.",
    ["The voice files are incomplete, so the voices and the microphone cannot start. Reinstall the Full download from Nexus Mods: extract it into the Cyberpunk 2077 folder and let it replace the files, then restart the game."] = "Os arquivos de voz estão incompletos, então as vozes e o microfone não conseguem iniciar. Reinstale o zip de instalação completo do Nexus Mods: extraia na pasta do Cyberpunk 2077 e deixe substituir os arquivos, depois reinicie o jogo.",
    ["Changes this mod’s menus and notices only.\n\nCharacter voices and the language you talk in are separate. The microphone uses this language as a hint for non-English speech."] = "Altera apenas os menus e avisos deste mod.\n\nAs vozes dos personagens e o idioma em que você fala são separados. O microfone usa este idioma como dica para falas em idiomas que não sejam inglês.",
    ["Deletes the saved key."] = "Apaga a chave salva.",
    ["The Convai cloud voice cannot use Natural speech, so it was turned off."] = "A voz na nuvem do Convai não pode usar a Fala natural, por isso ela foi desativada.",
    ["Custom endpoint"] = "Endpoint personalizado",
    ["Speaks up often"] = "Se manifesta com frequência",
    ["Speaks up rarely"] = "Se manifesta raramente",
    ["The address, API key and model ID of your OpenAI-compatible provider, and a connection test. Used when Custom is the Conversation provider."] = "O endereço, a chave de API e o ID do modelo do seu provedor compatível com a OpenAI, e um teste de conexão. Usado quando Personalizado é o Provedor de conversa.",
    ["OmniVoice · needs Omni pack"] = "OmniVoice · sem pacote Omni",
    ["OmniVoice · needs Omni voice"] = "OmniVoice · requer voz Omni",
    ["Requires the Companion voices to be an OmniVoice choice"] = "Exige que as vozes dos companheiros sejam a opção OmniVoice",
    ["V’s voice switches from OmniVoice to Pocket."] = "A voz de V muda de OmniVoice para Pocket.",
    ["V’s voice"] = "Voz do V",
    ["V (male voice)"] = "V (voz masculina)",
    ["V (female voice)"] = "V (voz feminina)",
    ["Used for V’s typed lines: Pocket, OmniVoice and the Voxtral cloud voice copy it."] = "Usada nas falas digitadas do V: o Pocket, o OmniVoice e a voz em nuvem do Voxtral a copiam.",
    ["V speaks with the voice of your installed V voice mod, or the shipped V voice."] = "O V fala com a voz do seu mod de voz do V instalado ou com a voz original dele.",
    ["Remove the voice clip? V goes back to the voice of your installed V voice mod, or the shipped V voice."] = "Remover o clipe de voz? O V volta para a voz do seu mod de voz do V instalado ou para a voz original dele.",
    ["OmniVoice needs an NVIDIA graphics card, and this PC has none that works. Replies show as text. Choose Pocket in Settings to hear voices."] = "O OmniVoice precisa de uma placa de vídeo NVIDIA, e este PC não tem nenhuma que funcione. As respostas aparecem como texto. Escolha Pocket em Configurações para ouvir as vozes.",
    ["OmniVoice needs an NVIDIA graphics card, and this PC has none that works. Companions are using {voice} instead."] = "O OmniVoice precisa de uma placa de vídeo NVIDIA, e este PC não tem nenhuma que funcione. Os companheiros estão usando {voice}.",
    ["OmniVoice needs NVIDIA"] = "OmniVoice precisa de NVIDIA",
    ["This PC has no NVIDIA graphics card, which OmniVoice needs. OmniVoice will not start here. Choose Pocket to hear voices."] = "Este PC não tem uma placa de vídeo NVIDIA, que o OmniVoice precisa. O OmniVoice não será iniciado aqui. Escolha Pocket para ouvir as vozes.",
    ["{voice} · needs NVIDIA card"] = "{voice} · requer placa NVIDIA",
    ["{language} replies show as text: the {language} multilingual pack is missing."] = "Respostas em {language} aparecem como texto: falta o pacote multilíngue de {language}.",
    ["French"] = "francês",
    ["Italian"] = "italiano",
    ["German"] = "alemão",
    ["Spanish"] = "espanhol",
    ["Portuguese"] = "português",
    ["OmniVoice needs more graphics memory than is free next to the game. Pocket is used."] = "O OmniVoice precisa de mais memória de vídeo do que a livre ao lado do jogo. Será usado o Pocket.",
    ["Windows ran out of memory for the voice. A larger paging file or closing other apps helps."] = "O Windows ficou sem memória para a voz. Ajuda aumentar o arquivo de paginação ou fechar apps.",
    ["OmniVoice needs 12 GB"] = "OmniVoice precisa de 12 GB",
    ["{voice} · needs 12 GB card"] = "{voice} · requer placa de 12 GB",
    ["The graphics card in this PC has less than the 12 GB OmniVoice needs next to the game. If it cannot start, Pocket is used. Choose Pocket to skip the wait."] = "A placa de vídeo deste PC tem menos que os 12 GB que o OmniVoice precisa junto com o jogo. Se não conseguir iniciar, o Pocket é usado. Escolha Pocket para pular a espera.",
    ["Forget all memories ({count} characters)"] = "Esquecer todas as lembranças ({count} personagens)",
    ["Dynamic info"] = "Info ao vivo",
    ["Location"] = "Localização",
    ["Time and weather"] = "Hora e clima",
    ["The hour of the day and the weather in Night City.\n\nOff: nobody is told the time or the weather, and the mod stops reading them from the game."] = "A hora do dia e o clima em Night City.\n\nDesligado: ninguém é informado da hora nem do clima, e o mod para de lê-los do jogo.",
    ["Company and vehicle"] = "Companhia e veículo",
    ["Who else is with V, whether V is on foot or in a vehicle, and what a companion is doing beside V.\n\nOff: none of this is sent, and the mod stops reading it from the game."] = "Quem mais está com V, se V está a pé ou em um veículo, e o que um companheiro faz ao lado de V.\n\nDesligado: nada disso é enviado, e o mod para de ler isso do jogo.",
    ["Health, heat and fights"] = "Saúde, procura e lutas",
    ["V’s health, the police heat on V, and the last fight V was in.\n\nOff: none of this is sent, and the mod stops reading it from the game."] = "A saúde de V, a procura da polícia contra V e a última luta em que V esteve.\n\nDesligado: nada disso é enviado, e o mod para de ler isso do jogo.",
    ["V’s money"] = "Dinheiro de V",
    ["A rough idea of how many eddies V has: nearly broke, short, comfortable or rich.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "Uma ideia aproximada de quantos eddies V tem: quase sem nada, pouco, confortável ou rico.\n\nDesligado: não é enviado, e o mod para de ler isso do jogo.",
    ["V’s gear and clothes"] = "Equipamento e roupas de V",
    ["What V wears and carries: clothes, weapons and cyberware that can be seen.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "O que V veste e carrega: roupas, armas e ciberimplantes visíveis.\n\nDesligado: não é enviado, e o mod para de ler isso do jogo.",
    ["V’s gender and lifepath"] = "Gênero e origem de V",
    ["Whether V is a woman or a man, and V’s lifepath: Nomad, Street Kid or Corpo.\n\nOff: it is not sent with a turn, and the mod stops reading it for that. Your story’s own facts may still reflect your lifepath."] = "Se V é mulher ou homem, e a origem de V: Nômade, Pivete ou Corpo.\n\nDesligado: não é enviado com cada turno, e o mod deixa de lê-lo para isso. Os fatos da sua história ainda podem refletir a sua origem.",
    ["Quest and journal"] = "Missões e diário",
    ["V’s tracked quest and its objectives, the jobs V has open and the journal history.\n\nWhat each character knows about your story stays on.\n\nOff: none of this is sent. The mod stops scanning the journal for it, unless Johnny’s remarks are on."] = "A missão que V acompanha e seus objetivos, os trabalhos em aberto de V e o histórico do diário.\n\nO que cada personagem sabe sobre a sua história continua ativo.\n\nDesligado: nada disso é enviado. O mod para de procurar isso no diário, a não ser que as falas do Johnny estejam ligadas.",
    ["Recent game dialogue"] = "Diálogos recentes",
    ["The last lines spoken in scenes and V’s chosen replies, so a character can pick up from what was just said.\n\nOff: they are not sent."] = "As últimas falas das cenas e as respostas escolhidas por V, para que um personagem possa continuar do que acabou de ser dito.\n\nDesligado: não são enviadas.",
    ["The Runtime is out of date. Get the full install zip."] = "O Runtime está desatualizado. Baixe o zip de instalação completo.",
    ["The Scripts and Runtime do not match. Update whichever is older. See Help in Settings."] = "Os Scripts e o Runtime não coincidem. Atualize o mais antigo. Veja Ajuda em Configurações.",
    ["Scripts {scripts} and Runtime {runtime} do not match: the Runtime is out of date. Extract the full install zip (AI-NPC-LLM-Companions, on Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Scripts {scripts} e Runtime {runtime} não coincidem: o Runtime está desatualizado. Extraia o zip de instalação completo (AI-NPC-LLM-Companions, no Nexus Mods) na pasta do Cyberpunk 2077 e depois reinicie o jogo.",
    ["Scripts {scripts} and Runtime {runtime} do not match. If the Scripts are older, install the update zip from Nexus Mods. If the Runtime is older, install the full install zip (AI-NPC-LLM-Companions). Extract into the Cyberpunk 2077 folder, then restart the game."] = "Scripts {scripts} e Runtime {runtime} não coincidem. Atualize o mais antigo: se os Scripts forem mais antigos, instale o zip de atualização do Nexus Mods; se o Runtime for mais antigo, instale o zip de instalação completo (AI-NPC-LLM-Companions). Extraia na pasta do Cyberpunk 2077 e reinicie o jogo.",
    ["The conversation service did not answer the setup check, so its Runtime is probably older than these Scripts. Extract the full install zip (AI-NPC-LLM-Companions, on Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "O serviço de conversa não respondeu à verificação de instalação, então o Runtime dele provavelmente é mais antigo que estes Scripts. Extraia o zip de instalação completo (AI-NPC-LLM-Companions, no Nexus Mods) na pasta do Cyberpunk 2077 e depois reinicie o jogo.",
    ["The Runtime update from {from} to {to} was never applied, so some Runtime files are old. Extract the full install zip (AI-NPC-LLM-Companions, on Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "A atualização do Runtime de {from} para {to} nunca foi aplicada, então alguns arquivos do Runtime estão antigos. Extraia o zip de instalação completo (AI-NPC-LLM-Companions, no Nexus Mods) na pasta do Cyberpunk 2077 e depois reinicie o jogo.",
    ["Runtime files are old. Get the full install zip."] = "Os arquivos do Runtime estão antigos. Baixe o zip completo.",
    ["Character unavailable in this game installation."] = "Personagem indisponível nesta instalação do jogo.",
    ["Message could not be delivered. Please try again."] = "Não foi possível entregar a mensagem. Tente novamente.",
    ["The conversation service could not reply. Please try again."] = "O serviço de conversa não conseguiu responder. Tente novamente.",
    ["Voice conversation failed. Check your microphone and try again."] = "A conversa por voz falhou. Verifique o microfone e tente novamente.",
    ["Companions now and then pause, hesitate, laugh or sigh, as their personality would. It stays rare.\n\nOmniVoice can voice laughs and sighs; the other voices only add pauses.\n\nNot available with Convai’s cloud voice: choosing it turns this off, and turning this on switches the voice to Pocket."] = "Os companheiros, de vez em quando, fazem pausas, hesitam, riem ou suspiram, conforme a personalidade deles. Isso continua raro.\n\nO OmniVoice pode dar risadas e suspiros; as outras vozes só acrescentam pausas.\n\nNão disponível com a voz na nuvem do Convai: escolhê-la desativa isto, e ativar isto muda a voz para o Pocket.",
    ["For testing and bug reports; leave it off for normal play.\n\nShows routine popups, writes a movement trace in the mod’s runtime folder, logs gesture decisions and adds itself to support reports.\n\nFailures, preparation progress and joined notices stay visible when it is off."] = "Para testes e relatórios de bugs; deixe desligado para jogar normalmente.\n\nMostra pop-ups de rotina, grava um registro de movimento na pasta do mod, registra decisões de gestos e entra nos relatórios de suporte.\n\nO progresso da preparação, avisos de entrada e falhas continuam visíveis quando está desligado.",
    ["Pocket: the lightest, on your CPU, about 0.2 s to the first word.\n\nOmniVoice: richer, needs a capable GPU and its pack, 1 to 2.5 s.\n\nVoxtral: cloud voices with your Mistral key. The companions’ voice loads no local model; V’s typed lines follow V’s own voice setting.\n\nConvai: its own cloud voice. A voice that cannot run shows replies as text."] = "Pocket: o mais leve, roda na CPU, primeira palavra em cerca de 0,2 s.\n\nOmniVoice: mais rico, exige GPU potente e o pacote dele, de 1 a 2,5 s.\n\nVoxtral: vozes na nuvem com sua chave do Mistral. As vozes dos companheiros não carregam modelo local; as falas digitadas por V seguem a configuração de voz de V.\n\nConvai: a voz própria do Convai, na nuvem. Voz que não roda mostra as respostas como texto.",
    ["The game’s own named characters, such as Judy, Jackie, Panam and Rogue, answer when you talk to them where they stand, with their own voice and memory.\n\nNothing else about them changes: they do not turn, move, gesture or follow, and stay quiet during scenes, quest conversations, fights and rides.\n\nTakes effect after you reload your save."] = "Os personagens nomeados do próprio jogo, como Judy, Jackie, Panam e Rogue, respondem quando você fala com eles onde estão, com a própria voz e memória.\n\nNada mais neles muda: não se viram, não se movem, não gesticulam nem seguem você. Ficam em silêncio durante cenas, conversas de missão, lutas e viagens.\n\nFaz efeito depois que você recarregar seu jogo salvo.",
    ["Mod Organizer 2. Files the mod creates go to its Overwrite folder; leave them there. Install the full install zip as one mod and update that mod with each new full install zip. Extract multilingual packs into that mod’s folder, not as new mods. Mention Mod Organizer 2 when you send a report."] = "Mod Organizer 2. Os arquivos criados pelo mod vão para a pasta Overwrite dele; deixe-os lá. Instale o zip de instalação completo como um mod e atualize esse mod com cada novo zip de instalação completo. Extraia os pacotes multilíngues na pasta desse mod, não como mods novos. Mencione o Mod Organizer 2 ao enviar um relatório.",
    ["With a mod manager: remove the old Scripts and Runtime mods, then install the full install zip as one mod."] = "Com um gerenciador de mods: remova os mods antigos Scripts e Runtime e depois instale o zip de instalação completo como um mod.",
    ["When something in the mod goes wrong, a short report goes to the developer.\n\nIt never holds keys, what you or the characters say, memories, audio or your Windows user name.\n\nIt holds the error, versions, settings, PC details (graphics card, processor, Windows, security software, drive, screen), mod names, setup check, reply timings and nearby log lines (for setup and script errors also the Cyber Engine Tweaks log)."] = "Se o mod der erro, um relatório curto vai ao desenvolvedor.\n\nNunca contém chaves de API, conversas, memórias, áudio ou seu usuário do Windows.\n\nContém o erro, versões, configurações, dados do PC (placa de vídeo, processador, Windows, segurança, drive, tela), mods, checagem de configuração, tempos de resposta e logs (em problemas de configuração e erros de script, também o do Cyber Engine Tweaks).",
    ["Some Runtime files are from a newer update than this Runtime says. Extract the full install zip (AI-NPC-LLM-Companions, on Nexus Mods) into the Cyberpunk 2077 folder again. Then restart the game."] = "Alguns arquivos do Runtime são de uma atualização mais recente do que a indicada por este Runtime. Extraia de novo o zip de instalação completo (AI-NPC-LLM-Companions, no Nexus Mods) na pasta do Cyberpunk 2077. Depois, reinicie o jogo.",
    ["Multilingual pack ({code})"] = "Pacote multilíngue ({code})",
