    ["{field}: {message}"] = "{field}: {message}",
    ["In use now"] = "Em uso agora",
    ["How each conversation option is told to answer. Every option has its own prompting. A change counts from the next reply, and nothing needs restarting."] = "Como cada opção de conversa deve responder. Cada opção tem o próprio prompt. Uma mudança vale a partir da próxima resposta, e nada precisa ser reiniciado.",
    ["The facts the characters get from the game and a short list of safety filters cannot be edited here. Convai’s prompting lives on Convai’s side."] = "Os fatos que os personagens recebem do jogo e uma lista curta de filtros de segurança não podem ser editados aqui. O prompt do Convai fica do lado do Convai.",
    ["Mistral and Local AI"] = "Mistral e Local AI",
    ["Lite and Standard are the two Local AI model sizes. “Mature on” is used while Mature content is on."] = "Lite e Standard são os dois tamanhos de modelo do Local AI. A variante “conteúdo maduro” é usada enquanto o conteúdo maduro estiver ligado.",
    ["Your Custom models and APIs"] = "Seus modelos e APIs personalizados",
    ["A Custom model appears here once you choose Custom as the conversation provider and set a model."] = "Um modelo personalizado aparece aqui quando você escolhe Personalizado como provedor de conversa e define um modelo.",
    ["From {min} to {max}."] = "De {min} a {max}.",
    ["Shipped: {value}"] = "Original: {value}",
    ["Rule {n}"] = "Regra {n}",
    ["Rule {n}, for a speaker with a reply length of its own"] = "Regra {n}, para quem tem tamanho de resposta próprio",
