    ["Other versions of this rule"] = "Outras versões desta regra",
    ["Leave a version empty to use the rule text."] = "Deixe uma versão vazia para usar o texto da regra.",
    ["For a speaker with a reply length of its own"] = "Para quem tem tamanho de resposta próprio",
    ["For Mature content"] = "Para conteúdo maduro",
    ["Shipped: off"] = "Original: não",
    ["Shipped: the mod’s own limit"] = "Original: o limite do próprio mod",
    ["before V’s words"] = "antes das falas de V",
    ["after V’s words"] = "depois das falas de V",
    ["Repeat the “where you are” sentence right before V’s words"] = "Repetir a frase “onde você está” logo antes das falas de V",
    ["The notes for this turn go"] = "As notas desta resposta vão",
    ["Output rules"] = "Regras de saída",
    ["The numbered rules the model reads before every reply. Use {name} for the character’s name and {words} for the reply length of a speaker that has one."] = "As regras numeradas que o modelo lê antes de cada resposta. Use {name} para o nome do personagem e {words} para o tamanho da resposta de quem tiver um.",
    ["Example replies"] = "Respostas de exemplo",
    ["Replies shown to the model after the rules. A small model may copy them word for word, so add none, or keep them short and plain."] = "Respostas mostradas ao modelo depois das regras. Um modelo pequeno pode copiá-las palavra por palavra, então não adicione nenhuma ou mantenha-as curtas e simples.",
    ["Add an example reply"] = "Adicionar uma resposta de exemplo",
    ["An example reply"] = "Uma resposta de exemplo",
    ["Example reply {n}"] = "Resposta de exemplo {n}",
    ["Opening line"] = "Linha inicial",
    ["The first line of the character text. Use {name} for the character’s name."] = "A primeira linha do texto do personagem. Use {name} para o nome do personagem.",
    ["The last thing the model reads before it answers. Use {name} for the character’s name and {words} for the reply length. The Mature setting adds its own clause after it."] = "A última coisa que o modelo lê antes de responder. Use {name} para o nome do personagem e {words} para o tamanho da resposta. A configuração de conteúdo maduro acrescenta uma frase própria depois.",
    ["Section headings"] = "Títulos das seções",
    ["The headings that mark each part of the prompt. Change the wording, not the order."] = "Os títulos que marcam cada parte do prompt. Mude a redação, não a ordem.",
    ["Layout"] = "Layout",
    ["Where some notes go in the prompt."] = "Onde algumas notas ficam no prompt.",
    ["Sampling"] = "Amostragem",
    ["How freely the model words its reply. Leave a box empty to use the shipped value."] = "Quão livremente o modelo escolhe as palavras da resposta. Deixe um campo vazio para usar o valor original.",
    ["Length limits"] = "Limites de tamanho",
    ["Shorten what the model reads, which makes replies faster. The mod’s own limits still apply, so these can only make things shorter."] = "Encurte o que o modelo lê, o que deixa as respostas mais rápidas. Os limites do próprio mod continuam valendo, então estes só podem deixar as coisas mais curtas.",
    ["Stop texts"] = "Textos de stop",
    ["Mature layer"] = "Camada adulta",
    ["The wording added while Mature content is on. The mod picks the explicit or the suggestive version of a line from what the loaded model allows, so edit the version your model uses. An emptied box leaves that line out. The adults-only line and the hard limits are always added last and cannot be edited."] = "As formulações acrescentadas enquanto o Conteúdo adulto está ativo. O mod escolhe a versão explícita ou sugestiva de uma fala conforme o que o modelo carregado permite, então edite a versão que o seu modelo usa. Um campo vazio tira aquela fala. A linha só para adultos e os limites rígidos são sempre acrescentados por último e não podem ser editados.",
    ["Speech line"] = "Linha de fala",
    ["Word bank"] = "Banco de palavras",
    ["Romance line"] = "Linha romântica",
    ["Closing clause"] = "Cláusula final",
    ["Tone line"] = "Linha de tom",
    ["Partner paragraph: affection and desire"] = "Parágrafo do parceiro: afeto e desejo",
    ["Partner paragraph: nothing invented"] = "Parágrafo do parceiro: nada inventado",
