    ["{part}, for models that keep sex suggestive"] = "{part}, para modelos que mantêm o sexo sugerido",
    ["This option does not get the Mature layer."] = "Esta opção não recebe a camada adulta.",
    ["Mature layer and closing line, for models that allow explicit sex"] = "Camada adulta e linha final, para modelos que permitem sexo explícito",
    ["Mature layer and closing line, for models that keep sex suggestive"] = "Camada adulta e linha final, para modelos que mantêm o sexo sugerido",
    ["A reply ends when the model writes one of these. Line breaks count. Up to {max}."] = "A resposta termina quando o modelo escreve um destes. Quebras de linha contam. Até {max}.",
    ["Add a stop text"] = "Novo texto de stop",
    ["A text that ends the reply"] = "Um texto que encerra a resposta",
    ["Stop text {n}"] = "Texto de stop {n}",
    ["Preview"] = "Prévia",
    ["The prompt text as the model would read it for a sample character. It follows your edits as you type, before you save."] = "O texto do prompt como o modelo o leria para um personagem de exemplo. Ele acompanha suas edições enquanto você digita, antes de salvar.",
    ["Sample character name"] = "Nome de exemplo",
    ["A speaker with a reply length of its own"] = "Quem tem tamanho de resposta próprio",
    ["Reply length in words"] = "Tamanho (em palavras)",
    ["Mature content is on"] = "Conteúdo maduro ativado",
    ["The preview waits until the problems in the form are fixed."] = "A prévia aguarda até que os problemas do formulário sejam corrigidos.",
    ["No example replies."] = "Sem respostas de exemplo.",
    ["No closing line."] = "Sem linha final.",
    ["Go back to the shipped prompting for {name}? Your changes to this part are removed."] = "Voltar ao prompt original de {name}? Suas mudanças nesta parte serão removidas.",
    ["Go back to the shipped prompting for {name}? All your changes to it are removed."] = "Voltar ao prompt original de {name}? Todas as suas mudanças nele serão removidas.",
    ["Back to the shipped prompting."] = "Voltar ao prompt original.",
    ["Prompting"] = "Prompt",
    ["Street reputation"] = "Reputação nas ruas",
    ["Gangs, the NCPD, corporations and the locals of each district remember what V did: Street Cred, choices in jobs, fights, crimes the police saw and how you treat people. It shapes their greeting, trust and help.\n\nOnly ordinary people, never named or story characters. It changes their words, nothing in the game."] = "Gangues, NCPD, corporações e o povo de cada distrito lembram o que V fez: Street Cred, escolhas nos trabalhos, brigas, crimes que a polícia viu e como você trata as pessoas. Isso molda a saudação, a confiança e a ajuda.\n\nSó pessoas comuns, nunca personagens com nome ou da história. Muda as palavras deles, nada no jogo.",
    ["NPCs react to threats and commands"] = "NPCs reagem a ameaças e ordens",
    ["Ordinary people you threaten run, cower or fight back, as their kind would: gang members and guards use their fists for an insult and their weapons for a death threat.\n\nThey may also do what you tell them, if they would: get down, stop, or get out of the vehicle.\n\nOnly ordinary people, never named or story characters, and never during scenes, quests or fights."] = "Pessoas comuns que você ameaça fogem, se encolhem ou revidam, conforme o seu tipo: membros de gangue e guardas usam os punhos diante de um insulto e as armas diante de uma ameaça de morte.\n\nElas também podem fazer o que você manda, se fariam: deitar no chão, parar ou sair do veículo.\n\nSó pessoas comuns, nunca personagens com nome ou da história, e nunca durante cenas, missões ou lutas.",
    ["Voice language"] = "Idioma da voz",
    ["English"] = "inglês",
    ["Automatic"] = "Automático",
    ["Polish"] = "polonês",
    ["Russian"] = "russo",
    ["Ukrainian"] = "ucraniano",
    ["Turkish"] = "turco",
    ["Czech"] = "tcheco",
    ["Hungarian"] = "húngaro",
    ["Japanese"] = "japonês",
    ["Korean"] = "coreano",
    ["Chinese"] = "chinês",
    ["Choose one of the listed reply languages."] = "Escolha um dos idiomas de resposta listados.",
    ["No speech was heard. Hold the talk key while you speak."] = "Nenhuma fala foi ouvida. Segure a tecla de voz enquanto fala.",
    ["Voice activation"] = "Ativação por voz",
    ["Voice activation could not open the microphone. Check your Windows input device."] = "A ativação por voz não conseguiu abrir o microfone. Verifique o dispositivo de entrada do Windows.",
    ["Voice input could not reach Convai. Hold the voice key again, or type."] = "A entrada de voz não conseguiu se conectar ao Convai. Segure a tecla de voz novamente ou digite.",
    ["Talk without a key. While you face a character or a companion is near, the mod listens and answers when you pause for about a second.\n\nNever during the game’s own scenes or choices, or while a character speaks. Nothing leaves your PC unless speech is heard. Headphones work best, but a Bluetooth headset’s microphone drops it to call quality while this listens."] = "Fale sem segurar tecla. Quando você estiver virado para um personagem ou houver um companheiro por perto, o mod escuta e responde após cerca de um segundo de pausa.\n\nNunca durante as cenas ou escolhas de diálogo do jogo, nem enquanto um personagem fala. Nada sai do seu PC sem fala ouvida. Fones de ouvido são melhores; o microfone de um headset Bluetooth o põe em qualidade de chamada enquanto escuta.",
    ["Opening microphone…"] = "Abrindo o microfone…",
    ["Speak now"] = "Fale agora",
    ["Type in the search box to find a model by name or record, for example “rita wheeler”. A part of a word is enough."] = "Digite na caixa de busca para encontrar um modelo pelo nome ou registro, por exemplo “rita wheeler”. Basta uma parte da palavra.",
    ["Content packs"] = "Pacotes de conteúdo",
    ["Add-ons that change how the characters talk."] = "Complementos que mudam a forma como os personagens falam.",
    ["Content packs add rules after yours. You cannot edit them here: turn a pack off under Settings > Content packs in the game."] = "Os pacotes de conteúdo adicionam regras depois das suas. Você não pode editá-los aqui: desative um pacote no jogo, em Configurações > Pacotes de conteúdo.",
    ["From the content pack {name}"] = "Do pacote de conteúdo {name}",
    ["Content packs that change this prompt: {names}. Your own changes stay on top of theirs, and Reset to default goes back to the pack’s wording."] = "Pacotes de conteúdo que mudam este prompt: {names}. Suas mudanças ficam acima das deles, e Restaurar padrão volta ao texto do pacote.",
    ["Memory in use"] = "Memória em uso",
    ["Normal memory"] = "Memória normal",
    ["Forget memories clears only the memory shown here. The other memory stays as it is."] = "Esquecer lembranças limpa só a memória mostrada aqui. A outra memória continua como está.",
    ["This clears the memory in use: {memory}."] = "Isso limpa a memória em uso: {memory}.",
    ["Backspace"] = "Backspace",
    ["Cancelled."] = "Cancelado.",
    ["Caps lock"] = "Caps Lock",
    ["Choose a key or a controller button."] = "Escolha uma tecla ou um botão do controle.",
    ["Choose the keys and controller buttons for talking by voice or text, the group chats and the Companion Manager. They work at once."] = "Escolha as teclas e os botões do controle para conversar por voz ou texto, para os chats em grupo e para o Gerenciador de companheiros. Elas funcionam na hora.",
    ["Choose the keys and controller buttons for the mod’s actions. Press Set, then the key or button you want. Esc or B cancels. A change works at once, and the keys you set in Cyber Engine Tweaks keep working. Pick keys the game does not already use."] = "Escolha as teclas e os botões do controle para as ações do mod. Pressione Definir e depois a tecla ou o botão desejado. Esc ou B cancela. A mudança funciona na hora, e as teclas definidas no Cyber Engine Tweaks continuam funcionando. Escolha teclas que o jogo ainda não usa.",
    ["Controller {button}"] = "Controle {button}",
    ["D-pad down"] = "Direcional para baixo",
    ["D-pad left"] = "Direcional para a esquerda",
    ["D-pad right"] = "Direcional para a direita",
    ["D-pad up"] = "Direcional para cima",
    ["Down arrow"] = "Seta para baixo",
    ["End"] = "End",
    ["Enter"] = "Enter",
    ["Group text chat"] = "Chat em grupo por texto",
    ["Group voice chat"] = "Chat em grupo por voz",
    ["Hold it to talk to the characters around you at once, and let go to send. Facing nobody, you talk to the first member of your party and two others from it."] = "Segure para falar com todos os personagens ao seu redor de uma vez e solte para enviar. Sem olhar para ninguém, você fala com o primeiro membro do seu grupo e com outros dois do grupo.",
    ["Hold it to talk to Johnny, the voice in your head, wherever you face, and let go to send. It needs Johnny in your head turned on in Settings."] = "Segure para falar com o Johnny, a voz na sua cabeça, para onde quer que você olhe, e solte para enviar. Precisa que o Johnny na sua cabeça esteja ativado nas Configurações.",
    ["Hold the key or button while you speak and let go to send, like the Cyber Engine Tweaks talk key. Facing nobody, you talk to the first member of your party."] = "Segure a tecla ou o botão enquanto fala e solte para enviar, como a tecla de falar do Cyber Engine Tweaks. Sem olhar para ninguém, você fala com o primeiro membro do seu grupo.",
    ["Home"] = "Home",
    ["Insert"] = "Insert",
    ["Key bindings"] = "Atalhos de teclas",
    ["Key bindings need Codeware, and this game does not have it. Open Help for what is missing."] = "Os atalhos de teclas precisam do Codeware, e este jogo não o tem. Abra Ajuda para ver o que falta.",
    ["Key or button"] = "Tecla ou botão",
    ["Left arrow"] = "Seta para a esquerda",
    ["Menu"] = "Menu",
    ["No key was pressed, so nothing changed."] = "Nenhuma tecla foi pressionada, então nada mudou.",
    ["Not available"] = "Indisponível",
    ["Not set"] = "Não definido",
    ["Num lock"] = "Num Lock",
    ["Page down"] = "Page Down",
    ["Page up"] = "Page Up",
    ["Pause"] = "Pause",
    ["Press it, then the key or controller button you want. Esc or B cancels. It works at once."] = "Pressione aqui e depois a tecla ou o botão do controle desejado. Esc ou B cancela. Funciona na hora.",
    ["Press it to open the Companion Manager while you play."] = "Pressione para abrir o Gerenciador de companheiros enquanto joga.",
    ["Press it to type to the character you face. Facing nobody, you type to the first member of your party."] = "Pressione para digitar para o personagem à sua frente. Sem olhar para ninguém, você digita para o primeiro membro do seu grupo.",
    ["Press it to type to Johnny, the voice in your head, wherever you face. It needs Johnny in your head turned on in Settings."] = "Pressione para digitar para o Johnny, a voz na sua cabeça, para onde quer que você olhe. Precisa que o Johnny na sua cabeça esteja ativado nas Configurações.",
    ["Press it to type to the characters around you at once. Facing nobody, you type to the first member of your party and two others from it."] = "Pressione para digitar para todos os personagens ao seu redor de uma vez. Sem olhar para ninguém, você digita para o primeiro membro do seu grupo e para outros dois do grupo.",
    ["Press the key or controller button for {action}. Esc or B cancels."] = "Pressione a tecla ou o botão do controle para {action}. Esc ou B cancela.",
    ["Print screen"] = "Print Screen",
    ["Remove the key or button you set here."] = "Remove a tecla ou o botão definido aqui.",
    ["Right arrow"] = "Seta para a direita",
    ["Scroll lock"] = "Scroll Lock",
    ["Space"] = "Espaço",
    ["Tab"] = "Tab",
    ["Talk by text"] = "Conversar por texto",
    ["Talk by voice"] = "Conversar por voz",
    ["Talk to Johnny by text"] = "Conversar com o Johnny por texto",
    ["Talk to Johnny by voice"] = "Conversar com o Johnny por voz",
    ["That key is already used for another action."] = "Essa tecla já está em uso por outra ação.",
    ["The mod’s key bindings could not be loaded. Open Help for what is wrong."] = "Não foi possível carregar os atalhos de teclas do mod. Abra Ajuda para ver o que está errado.",
    ["The mod’s scripts did not load, so no key can be set. Open Help for what is wrong."] = "Os scripts do mod não carregaram, então nenhuma tecla pode ser definida. Abra Ajuda para ver o que está errado.",
    ["Up arrow"] = "Seta para cima",
    ["View"] = "Exibir",
    ["{action} cleared."] = "Atalho de {action} removido.",
    ["{action} is set to {key}."] = "{action} está definido como {key}.",
    ["{key} is already used for {other}. Choose another."] = "{key} já está em uso para {other}. Escolha outra.",
    ["10 minutes"] = "10 minutos",
    ["2 minutes"] = "2 minutos",
    ["5 minutes"] = "5 minutos",
    ["Cancel this meeting. She is not told."] = "Cancelar o encontro. Ela não fica sabendo.",
    ["Car"] = "Carro",
    ["Choose how long she waits."] = "Escolha quanto tempo ela espera.",
    ["Choose how she arrives."] = "Escolha como ela chega.",
    ["Choose one of the listed options."] = "Escolha uma das opções listadas.",
    ["Choose when she arrives."] = "Escolha quando ela chega.",
    ["Companions travel to you when you invite them: they walk or drive in, text you, wait, and remember if you never come.\n\nOff by default."] = "Os companheiros vêm até você quando os convida: andam ou dirigem, mandam mensagem, esperam e lembram se você nunca aparecer.\n\nDesativado por padrão.",
    ["Fine. Call me when you know what you want."] = "Tudo bem. Me chama quando souber o que quer.",
    ["How long she waits"] = "Quanto tempo ela espera",
    ["How long she waits for you after arriving right now. After a timed arrival she waits as long as the delay you chose. The wait stops while you are in a fight, a scene or a menu."] = "Quanto tempo ela espera por você ao chegar agora. Após uma chegada programada, ela espera o tempo do atraso escolhido. A espera para durante luta, cena ou menu.",
    ["How she arrives"] = "Como ela chega",
    ["I waited {minutes} minutes at {place} and you never showed. Forget it."] = "Esperei {minutes} minutos em {place} e você nunca apareceu. Esquece.",
    ["I'm here at {place}. Where are you?"] = "Estou aqui em {place}. Onde você está?",
    ["Immersive invitations"] = "Convites imersivos",
    ["In 10 minutes"] = "Em 10 minutos",
    ["In 2 minutes"] = "Em 2 minutos",
    ["In 5 minutes"] = "Em 5 minutos",
    ["Invite a companion and she really travels to you: she appears out of sight, walks or drives in, texts you when she is there and waits for you."] = "Convide um companheiro e ela realmente vai até você: aparece fora de vista, anda ou dirige até lá, avisa por mensagem quando chega e espera por você.",
    ["Meet at my waypoint when I ask"] = "Encontrar no meu ponto quando eu pedir",
    ["Off: Invite brings a companion to your side at once.\n\nOn: a companion you invite, by the Invite button, the Contacts tab or a text, travels to you and arrives after the time you choose here. She texts you when she is there, waits, and leaves angry (and remembers it) if you never come."] = "Desativado: Convidar traz um companheiro ao seu lado na hora.\n\nAtivado: um companheiro que você convida, pelo botão Convidar, pela aba Contatos ou por mensagem, vai até você e chega depois do tempo escolhido aqui. Ela manda mensagem quando chega, espera e vai embora irritada (e se lembra disso) se você nunca aparecer.",
    ["Right now"] = "Agora",
    ["Right now: she is on her way as soon as she is ready.\n\nIn 2, 5 or 10 minutes: real minutes of play, so she arrives at that time. She then waits as long as that delay."] = "Agora: ela vai até você assim que estiver pronta.\n\nEm 2, 5 ou 10 minutos: minutos reais de jogo, então ela chega nessa hora. Depois espera pelo tempo desse atraso.",
    ["She texts you"] = "Ela manda mensagem",
    ["She texts you when she arrives, when you cancel and when she gives up. Off: no texts (she still remembers being stood up)."] = "Ela avisa ao chegar, ao você cancelar e ao desistir. Desativado: sem mensagens (ela lembra mesmo assim de ser deixada plantada).",
    ["Something came up and I can't make it. Sorry."] = "Apareceu uma coisa e não vou conseguir. Desculpa.",
    ["Walk"] = "A pé",
    ["Walk: she appears out of your sight and walks to you.\n\nCar: when a road is near she drives in, stops on the road, gets out and walks the rest. Without a road she walks. The car stays near for a ride, and is removed when she leaves your group or you both go far from it."] = "A pé: ela aparece fora da sua vista e anda até você.\n\nCarro: quando há uma estrada perto, ela chega dirigindo, para na estrada, desce e anda o resto. Sem estrada ela anda. O carro fica por perto para a viagem e some quando ela deixa seu grupo ou quando os dois se afastam dele.",
    ["When she arrives"] = "Quando ela chega",
    ["When you ask her to come to your waypoint and a map pin is set, she goes there and says so. Off: she always comes to where you are."] = "Quando você pede que ela vá ao seu ponto e há um marcador no mapa, ela vai até lá e avisa. Desativado: ela sempre vem até onde você está.",
    ["Your position cannot be read yet."] = "Não dá para ler sua posição ainda.",
    ["on her way"] = "a caminho",
    ["the meeting spot"] = "o ponto de encontro",
    ["waiting at {place}"] = "esperando em {place}",
    ["{name} is already on the way."] = "{name} já está a caminho.",
    ["{name} is on her way."] = "{name} está a caminho.",
    ["{name} is on her way. About {minutes} minutes."] = "{name} está a caminho. Cerca de {minutes} minutos.",
    ["{name} · {state}"] = "{name} · {state}",
    ["{name}: Good to see you. Let us go."] = "{name}: Que bom te ver. Vamos lá.",
    ["Corpo Plaza"] = "Corpo Plaza",
    ["Heywood Glen"] = "Heywood Glen",
    ["Megabuilding H10"] = "Megabuilding H10",
    ["Move out"] = "Fazer sair de casa",
    ["That companion is not available."] = "Esse companheiro não está disponível.",
    ["Watson Northside"] = "Watson Northside",
    ["Westbrook Japantown"] = "Westbrook Japantown",
    ["You do not have that apartment."] = "Você não tem esse apartamento.",
    ["at home"] = "em casa",
    ["out"] = "fora",
    ["with you"] = "com você",
    ["{count} more housemates"] = "mais {count} colegas de casa",
    ["{name} has moved out."] = "{name} saiu de casa.",
    ["{name} is back at home."] = "{name} voltou para casa.",
    ["{name} joins you."] = "{name} se junta a você.",
    ["{name} moves into {apartment}."] = "{name} se muda para {apartment}.",
    ["{name} now lives in {apartment} and stays in your party until sent home."] = "{name} agora mora em {apartment} e continua no seu grupo até voltar para casa.",
    ["{name} stops living at your place. She stays as she is otherwise."] = "{name} deixa de morar com você. Fora isso, nada muda.",
    ["{name} · lives in {apartment} · {state}"] = "{name} · mora em {apartment} · {state}",
    ["Companions change outfits"] = "Companheiros trocam de roupa",
    ["Your party’s companions change outfits now and then: another look by day and by night, and casual clothes at home, where the character has them.\n\nOnly out of your sight, never in front of you, and only for your party’s own copies, never the game’s own characters. Turning this off keeps what they wear now."] = "Os companheiros do seu grupo trocam de roupa de tempos em tempos: outro visual de dia e outro à noite, e roupas casuais em casa, quando o personagem as tiver.\n\nSomente fora da sua vista, nunca na sua frente, e apenas para as cópias do próprio grupo, nunca para os personagens do jogo. Desligar essa opção mantém as roupas que eles estão usando agora.",
    ["Choose how often companions speak up."] = "Escolha com que frequência os companheiros se manifestam.",
    ["Companions speak up"] = "Companheiros se manifestam",
    ["How V is doing according to other mods, when they are installed: Dark Future’s tiredness, hunger, thirst, nerve and addictions, for example. Also what V visibly wears while an Equipment-EX outfit is on, so characters describe the outfit and not the clothes it hides.\n\nOff by default. Off: it is not sent, and nothing is read from those mods."] = "Como V está segundo outros mods, quando instalados: por exemplo, cansaço, fome, sede, nervos e vícios do Dark Future. Também o que V veste de forma visível enquanto um visual do Equipment-EX está ativo, para que os personagens descrevam o visual e não as roupas que ele esconde.\n\nDesativado por padrão. Desativado: nada é enviado, e nada é lido desses mods.",
    ["How long it has been since V last talked to this character, in the game and in real days: since last night, or days ago. Said only when the gap is long enough to matter, and not again in the same conversation.\n\nOff: it is not sent, and the mod stops reading the game clock for it."] = "Quanto tempo se passou desde a última vez que V conversou com este personagem, no jogo e em dias reais: desde ontem à noite, ou há dias. Só é dito quando o intervalo é longo o bastante para importar, e não de novo na mesma conversa.\n\nDesativado: nada é enviado, e o mod deixa de ler o relógio do jogo para isso.",
    ["Music and TV"] = "Música e TV",
    ["Other mods’ state"] = "Estado de outros mods",
    ["Speaks up normally"] = "Se manifesta normalmente",
    ["The song playing on the car radio while V rides with the character, or on V’s pocket radio, and what is on a TV near V.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "A música que toca no rádio do carro quando V anda com o personagem, ou no rádio de bolso de V, e o que está passando em uma TV perto de V.\n\nDesativado: nada é enviado, e o mod deixa de ler isso do jogo.",
    ["Time since last talk"] = "Tempo desde a última conversa",
    ["Companions in your party sometimes start talking on their own, at a calm moment or after a scene. With two or more near you, it is often a short chat between up to three of them, and you can join in by talking. Never during fights, scenes, calls or menus.\n\nRarely: about 2 an hour. Normally: about 4. Often (the default): about 6.\n\nWith Johnny speaking up too, the rates add up and they take turns."] = "Os companheiros às vezes falam por conta própria, num momento calmo ou após uma cena. Com dois ou mais por perto, é um papo curto entre até três, em que você pode entrar. Nunca em lutas, cenas, ligações ou menus.\n\nRaramente: cerca de 2 por hora de jogo. Normalmente: cerca de 4. Com frequência (padrão): cerca de 6.\n\nQuando o Johnny também se manifesta, as duas taxas se somam e os falantes se revezam.",
    ["Johnny Silverhand answers the Talk to Johnny keys, as the voice in V’s head, once the story has him there. Give Talk to Johnny a key on the Key bindings page: none is set by default.\n\nOn: he answers when you talk to him. Rarely: he also speaks up on his own, about 2 an hour. Normally: about 4. Often: about 6.\n\nWith companions speaking up too, the rates add up and they take turns."] = "Johnny Silverhand atende às teclas Conversar com o Johnny, como voz na cabeça de V, quando a trama o coloca ali. Atribua uma tecla a Conversar com o Johnny em Atalhos de teclas: nenhuma vem definida.\n\nAtivado: responde quando você fala com ele. Raramente: fala sozinho, cerca de 2 vezes por hora. Normalmente: 4. Com frequência: 6.\n\nCom os companheiros falando também, as taxas se somam e eles se revezam.",
    ["Choose which live game info the characters are told, such as location, time, weather, company, health, money, gear, quests, music and TV, and other mods’ state.\n\nAll on by default except other mods’ state, which is off. An off kind is not sent to any conversation provider."] = "Escolha quais informações ao vivo do jogo são repassadas aos personagens, como localização, hora, clima, companhia, saúde, dinheiro, equipamento, missões, música e TV, e o estado de outros mods.\n\nTudo vem ativado por padrão, exceto o estado de outros mods, que vem desativado. Um tipo desativado não é enviado a nenhum provedor de conversa.",
    ["Housemates"] = "Colegas de casa",
    ["Housemates talk to each other"] = "Colegas de casa conversam entre si",
    ["When two or more housemates are home with you, they talk to each other now and then."] = "Quando dois ou mais colegas de casa estão em casa com você, eles conversam entre si de vez em quando.",
    ["Characters you tell they can stay at your place move into your apartments and live there."] = "Os personagens a quem você diz que podem ficar na sua casa se mudam para os seus apartamentos e moram lá.",
    ["Characters you tell they can stay at your place move into your apartments and live there.\n\nOff by default."] = "Os personagens a quem você diz que podem ficar na sua casa se mudam para os seus apartamentos e moram lá.\n\nDesativado por padrão.",
    ["On: characters you tell they can stay at your place move into your apartments and live there, and you can call them along.\n\nOff: nothing of this runs. Turning it off removes them from your apartments but remembers who lived there, so turning it on brings them back."] = "Ativado: os personagens a quem você diz que podem ficar na sua casa se mudam para os seus apartamentos e moram lá, e você pode levá-los junto.\n\nDesativado: nada disso funciona. Ao desativar, eles saem dos seus apartamentos, mas fica guardado quem morava lá, então voltam quando você ativa de novo.",
    ["OmniVoice Python"] = "OmniVoice Python",
    ["OmniVoice’s code could not load in it"] = "o código do OmniVoice não conseguiu carregar",
    ["PyTorch is not installed in it"] = "PyTorch não está instalado nele",
    ["Your own Python (omni-python.txt) is being tested. Open this page again in a minute."] = "Seu próprio Python (omni-python.txt) está sendo testado. Abra esta página novamente em um minuto.",
    ["Your own Python (omni-python.txt) is tested when OmniVoice starts or when this page checks again."] = "Seu próprio Python (omni-python.txt) é testado quando OmniVoice inicia ou quando esta página verifica novamente.",
    ["Your own Python (omni-python.txt) runs OmniVoice with {backend} on {card}. Experimental."] = "Seu próprio Python (omni-python.txt) executa OmniVoice com {backend} em {card}. Experimental.",
    ["Your own Python (omni-python.txt) was not used: {reason}. OmniVoice uses the Runtime’s Python, which needs an NVIDIA card."] = "Seu próprio Python (omni-python.txt) não foi usado: {reason}. OmniVoice usa o Python do Runtime, que precisa de uma placa NVIDIA.",
    ["a test on the graphics card failed"] = "um teste na placa de vídeo falhou",
    ["it did not start or did not answer in time"] = "não iniciou ou não respondeu a tempo",
    ["its PyTorch finds no graphics card (no CUDA or ROCm)"] = "seu PyTorch não encontra placa de vídeo (sem CUDA ou ROCm)",
    ["the OmniVoice pack is not installed"] = "o pacote OmniVoice não está instalado",
    ["the file does not name a python.exe that exists"] = "o arquivo não especifica um python.exe que existe",
    ["the module {module} is missing in it"] = "o módulo {module} está faltando nele",
    ["1 minute"] = "1 minuto",
    ["2 people"] = "2 pessoas",
    ["3 people"] = "3 pessoas",
    ["4 people"] = "4 pessoas",
    ["Every character who lives at your place moves out at once, from every apartment. Party members who do not live there are not touched. A housemate who is with you stays in your party."] = "Todos os personagens que moram com você se mudam de uma vez, de todos os apartamentos. Membros do grupo que não moram lá não são afetados. Um colega de casa que está com você permanece no grupo.",
    ["Evict"] = "Despejar",
    ["Evict all housemates"] = "Despejar todos os colegas de casa",
    ["Housemates in one chat"] = "Colegas de casa em um chat",
    ["Housemates moved out: {count}"] = "Colegas de casa se mudaram: {count}",
    ["How long the housemates stay quiet after a chat before they may start another. The Companions speak up setting still limits how many chats come in an hour."] = "Quanto tempo os colegas de casa ficam em silêncio após um chat antes de poder começar outro. A configuração Companheiros se manifestam ainda limita quantos chats chegam em uma hora.",
    ["How many housemates join one chat when that many are home near each other. They speak one at a time. With fewer at home, the chat is as big as it can be."] = "Quantos colegas de casa participam de um chat quando esse número está em casa perto um do outro. Falam um de cada vez. Com menos em casa, o chat é tão grande quanto pode ser.",
    ["Move-in apartment"] = "Apartamento de mudança",
    ["Nobody lives at your place."] = "Ninguém mora na sua casa.",
    ["Pause between chats"] = "Pausa entre chats",
    ["Where a character moves in when you say she can stay but name no apartment and you are not standing in one of yours.\n\nAsk me: she asks which one. Otherwise she takes the apartment you pick here. Only the apartments you own are listed."] = "Onde um personagem se muda quando você diz que ela pode ficar mas não nomeia um apartamento e você não está em um dos seus.\n\nPergunte-me: ela pergunta qual. Caso contrário, ela pega o apartamento que você escolhe aqui. Apenas os apartamentos que você possui são listados.",
    ["Ask me"] = "Pergunte-me",
    ["Could not start"] = "Não foi possível iniciar",
    ["Did not start"] = "Não iniciou",
    ["If the folder is there, the newest log in red4ext/logs says why RED4ext did not load it: an antivirus that removed a file, or a missing Visual C++ runtime."] = "Se a pasta estiver lá, o log mais recente em red4ext/logs mostra por que o RED4ext não a carregou: um antivírus removeu um arquivo ou falta o Visual C++ runtime.",
    ["Load a save first. A key can be set only while a game is loaded."] = "Carregue um save primeiro. Uma tecla só pode ser definida com um jogo carregado.",
    ["No key press reached the mod, so nothing changed. If keys do not arrive from this menu, set the key in Cyber Engine Tweaks’ Bindings: it works the same."] = "Nenhuma tecla pressionada chegou ao mod, então nada mudou. Se as teclas não chegarem por este menu, defina a tecla nos atalhos do Cyber Engine Tweaks: funciona da mesma forma.",
    ["Runtime incomplete"] = "Runtime incompleto",
    ["Runtime not loaded"] = "Runtime não carregado",
    ["Service not running ({reason})"] = "Serviço não está em execução ({reason})",
    ["The Runtime’s plugin is loaded, but the conversation service left no trace in this session. launcher.log in red4ext/plugins/AiNpcCyberpunkCode says why: launcher.ini switched off, Node missing, or Node blocked by a security program. Fix that, then restart the game."] = "O plugin do Runtime está carregado, mas o serviço de conversa não deixou nenhum rastro nesta sessão. O launcher.log em red4ext/plugins/AiNpcCyberpunkCode mostra o motivo: launcher.ini desligado, Node ausente ou Node bloqueado por um programa de segurança. Corrija isso e reinicie o jogo.",
    ["The conversation service cannot see this mod’s folder in the game: a mod manager’s virtual folders, or a folder it may not read. Extract the Runtime straight into the Cyberpunk 2077 folder, or start the game from the mod manager that holds the Runtime."] = "O serviço de conversa não consegue ver a pasta deste mod no jogo: pastas virtuais de um gerenciador de mods, ou uma pasta que ele não tem permissão para ler. Extraia o Runtime direto na pasta do Cyberpunk 2077, ou inicie o jogo pelo gerenciador de mods que tem o Runtime.",
    ["The conversation service was started and never reported back. A security program probably stopped it at once, or Node cannot run on this PC. Allow red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe in your security program, then restart the game."] = "O serviço de conversa foi iniciado, mas nunca respondeu. Provavelmente um programa de segurança o parou logo de cara, ou o Node não consegue rodar neste PC. Permita red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe no seu programa de segurança e reinicie o jogo.",
    ["Windows would not let the game start the conversation service (error {error}). A security program may be blocking node.exe in red4ext/plugins/AiNpcCyberpunkMod/app/node: allow it, then restart the game."] = "O Windows não permitiu que o jogo iniciasse o serviço de conversa (erro {error}). Um programa de segurança pode estar bloqueando o node.exe em red4ext/plugins/AiNpcCyberpunkMod/app/node: permita e reinicie o jogo.",
    ["Add a server address first."] = "Adicione primeiro um endereço de servidor.",
    ["Asks the server three times who it is and shows whether it is reachable, how long it takes to answer and its version. It sends no speech."] = "Pergunta ao servidor três vezes quem ele é e mostra se ele está acessível, quanto tempo leva para responder e a versão. Não envia fala.",
    ["Connected. The server speaks with {voice}."] = "Conectado. O servidor fala com {voice}.",
    ["Custom voices"] = "Vozes personalizadas",
    ["Deletes the saved server address. Remote OmniVoice needs one to speak."] = "Exclui o endereço de servidor salvo. O OmniVoice remoto precisa de um para falar.",
    ["It answers in {ms} ms."] = "Responde em {ms} ms.",
    ["Its voice runs on {device}."] = "A voz dele roda em {device}.",
    ["Loading"] = "Carregando",
    ["Not connected. Replies show as text until the server answers."] = "Não conectado. As respostas aparecem como texto até o servidor responder.",
    ["Nothing answered at that address. Check that the server is running, that the address and port are right and that both PCs are on the same network. A server started with its default only listens on its own PC: start it with the listen address 0.0.0.0."] = "Nada respondeu nesse endereço. Verifique se o servidor está em execução, se o endereço e a porta estão corretos e se os dois PCs estão na mesma rede. Um servidor iniciado com o padrão escuta somente no próprio PC: inicie-o com o endereço de escuta 0.0.0.0.",
    ["Off. OmniVoice runs on this PC."] = "Desligado. O OmniVoice roda neste PC.",
    ["On, but no server address is saved. OmniVoice cannot speak yet."] = "Ligado, mas nenhum endereço de servidor está salvo. O OmniVoice ainda não pode falar.",
    ["On, but no server address is saved. Pocket is used until you add one."] = "Ligado, mas nenhum endereço de servidor está salvo. O Pocket é usado até você adicionar um.",
    ["On, but no server address is saved. The server is not used yet."] = "Ligado, mas nenhum endereço de servidor está salvo. O servidor ainda não é usado.",
    ["On, but a cloud voice is chosen under Companion voices, so the server is not used."] = "Ligado, mas em Vozes dos companheiros está escolhida uma voz na nuvem, então o servidor não é usado.",
    ["On. Waiting for the conversation service."] = "Ligado. Aguardando o serviço de conversa.",
    ["Paste address"] = "Colar endereço",
    ["Remote OmniVoice"] = "OmniVoice remoto",
    ["Render the voices on another PC or graphics card that runs the OmniVoice server, so this PC keeps its frames.\n\nTurn it on, press Apply and add the server address below. The server then speaks for every Pocket or OmniVoice choice under Companion voices; a cloud voice stays as chosen. If it cannot be reached, replies show as text and the mod retries every few seconds."] = "Renderiza as vozes em outro PC ou placa de vídeo com o servidor do OmniVoice, para que este PC mantenha seus quadros.\n\nLigue, pressione Aplicar e adicione o endereço do servidor abaixo. Ligado, o servidor fala por cada escolha de Pocket ou OmniVoice em Vozes dos companheiros; vozes na nuvem não mudam. Sem conexão, as respostas aparecem como texto e o mod tenta de novo a cada poucos segundos.",
    ["Render the OmniVoice voices on another PC or graphics card that runs the OmniVoice server."] = "Renderiza as vozes do OmniVoice em outro PC ou placa de vídeo que executa o servidor do OmniVoice.",
    ["Render Pocket and OmniVoice voices on another PC or graphics card: the on/off switch, the server address and a connection test. It works whichever of those voices is chosen above."] = "Renderiza as vozes do Pocket e do OmniVoice em outro PC ou placa de vídeo: a chave liga/desliga, o endereço do servidor e um teste de conexão. Funciona com qualquer uma dessas vozes escolhida acima.",
    ["Server address"] = "Endereço do servidor",
    ["Something answered, but it is not the OmniVoice server. Check the port."] = "Algo respondeu, mas não é o servidor do OmniVoice. Verifique a porta.",
    ["Start the OmniVoice server on the other PC. Its window shows the address to use, for example 192.168.1.20:8765. Copy it, then choose Paste address. It is read from the clipboard once and saved on this computer.\n\nOn the same PC use 127.0.0.1:8765. You can also write address=192.168.1.20:8765 in player-remote-omnivoice.txt in the conversation service folder.\n\nNothing is sent to it until Remote OmniVoice is on and OmniVoice is chosen, or you press Test."] = "Inicie o servidor do OmniVoice no outro PC. A janela dele mostra o endereço a usar, por exemplo 192.168.1.20:8765. Copie-o e depois escolha Colar endereço. Ele é lido da área de transferência uma vez e salvo neste computador.\n\nNo mesmo PC, use 127.0.0.1:8765. Você também pode escrever address=192.168.1.20:8765 em player-remote-omnivoice.txt na pasta do serviço de conversa.\n\nNada é enviado a ele até que o OmniVoice remoto esteja ligado e o OmniVoice escolhido, ou até você pressionar Testar.",
    ["Status"] = "Status",
    ["The OmniVoice server cannot be reached. Replies show as text until it answers. The mod asks it again every few seconds."] = "Não é possível acessar o servidor do OmniVoice. As respostas aparecem como texto até ele responder. O mod pergunta de novo a cada poucos segundos.",
    ["The clipboard does not hold a server address."] = "A área de transferência não contém um endereço de servidor.",
    ["The clipboard is empty. Copy the address first."] = "A área de transferência está vazia. Copie o endereço primeiro.",
    ["The port must be a number from 1 to 65535."] = "A porta deve ser um número de 1 a 65535.",
    ["The server address was removed."] = "O endereço do servidor foi removido.",
    ["The server answered but could not load its voice. Its window says why."] = "O servidor respondeu, mas não conseguiu carregar a voz. A janela dele informa o motivo.",
    ["The server answered but is still loading its voice. Try again in a minute."] = "O servidor respondeu, mas ainda está carregando a voz. Tente de novo em um minuto.",
    ["The server is another version. Use the server folder and the mod from the same release."] = "O servidor é de outra versão. Use a pasta do servidor e o mod da mesma versão.",
    ["The server is ready."] = "O servidor está pronto.",
    ["The server refused the request."] = "O servidor recusou a solicitação.",
    ["The server took too long to answer."] = "O servidor demorou demais para responder.",
    ["Use the address only: no user name, no path, no #."] = "Use apenas o endereço: sem nome de usuário, sem caminho, sem #.",
    ["Use the address the server window shows, such as 192.168.1.20:8765, without https://."] = "Use o endereço que a janela do servidor mostra, como 192.168.1.20:8765, sem https://.",
    ["Waiting for the server to answer…"] = "Aguardando o servidor responder…",
    ["Whether the server is in use right now. It is checked when a voice is needed and again every few seconds after a failure, never while you play."] = "Indica se o servidor está em uso agora. É verificado quando uma voz é necessária e de novo a cada poucos segundos após uma falha, nunca enquanto você joga.",
    ["Your own character, made in the character editor."] = "Seu próprio personagem, criado no editor de personagens.",
    ["Build for your game"] = "Build para o seu jogo",
    ["Your game is {game} but the Runtime is the one for game {runtime}. Get the full install zip for game {game} from the mod’s Nexus Mods page (main file for game 2.5, optional file for game 2.31) and extract it into the Cyberpunk 2077 folder over this one, then restart the game."] = "Seu jogo é {game}, mas o Runtime é o do jogo {runtime}. Baixe o zip de instalação completo do jogo {game} na página do mod no Nexus Mods (arquivo principal para o jogo 2.5, arquivo opcional para o jogo 2.31), extraia na pasta do Cyberpunk 2077 sobre a atual e depois reinicie o jogo.",
    ["Your game is {game} but the Scripts are the build for game {scripts}. Get the update zip for game {game} from the mod’s Nexus Mods page (the update file is for game 2.5, the optional update file for game 2.31) and install it over these, then restart the game."] = "Seu jogo é {game}, mas os Scripts são o build para o jogo {scripts}. Baixe o zip de atualização do jogo {game} na página do mod no Nexus Mods (arquivo de atualização para o jogo 2.5, arquivo opcional de atualização para o jogo 2.31), instale-o sobre os atuais e depois reinicie o jogo.",
    ["Your game is {game} but the Scripts and the Runtime are the build for game {scripts}. Get the full install zip for game {game} from the mod’s Nexus Mods page (main file for game 2.5, optional file for game 2.31) and extract it into the Cyberpunk 2077 folder over these, then restart the game."] = "Seu jogo é {game}, mas os Scripts e o Runtime são o build para o jogo {scripts}. Baixe o zip de instalação completo do jogo {game} na página do mod no Nexus Mods (arquivo principal para o jogo 2.5, arquivo opcional para o jogo 2.31), extraia na pasta do Cyberpunk 2077 sobre os atuais e depois reinicie o jogo.",
    ["The Scripts are the build for game {scripts} but the Runtime is the build for game {runtime}, and the game version matches neither. Extract the full install zip made for the same game as yours (from Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Os Scripts são o build para o jogo {scripts}, mas o Runtime é o build para o jogo {runtime}, e a versão do jogo não corresponde a nenhum dos dois. Extraia na pasta do Cyberpunk 2077 o zip de instalação completo feito para o mesmo jogo que o seu (do Nexus Mods) e depois reinicie o jogo.",
    ["The Runtime is for game {other}, yours is {game}. Get the full install zip for {game}."] = "Runtime do jogo {other}, o seu é {game}. Baixe o zip completo para {game}.",
    ["The Scripts are for game {other}, yours is {game}. Get the update zip for {game}."] = "Scripts do jogo {other}, o seu é {game}. Baixe o zip de atualização para {game}.",
    ["This mod is for game {other}, yours is {game}. Get the full install zip for {game}."] = "Mod do jogo {other}, o seu é {game}. Baixe o zip completo para {game}.",
    ["Scripts are for game {scripts}, Runtime for {runtime}. They must match. See Help in Settings."] = "Scripts {scripts}, Runtime {runtime}. Devem coincidir: veja Ajuda em Configurações.",
    ["Choose one of the listed microphones."] = "Escolha um dos microfones da lista.",
    ["Microphone"] = "Microfone",
    ["The microphone you chose in Settings ({chosen}) is not connected, so the Windows default input is used: {name}."] = "O microfone que você escolheu em Configurações ({chosen}) não está conectado, então a entrada padrão do Windows é usada: {name}.",
    ["The microphone you chose in Settings is not connected, so the Windows default input is used."] = "O microfone que você escolheu em Configurações não está conectado, então a entrada padrão do Windows é usada.",
    ["Windows default"] = "Padrão do Windows",
    ["not connected"] = "não conectado",
    ["{name}, chosen in Settings > Voices."] = "{name}, escolhido em Configurações > Vozes.",
    ["{name}, the Windows default input. Settings > Voices > Microphone chooses another."] = "{name}, a entrada padrão do Windows. Outra você escolhe em Configurações > Vozes > Microfone.",
    ["Revenge ambushes"] = "Emboscadas de vingança",
    ["Speak dialogue choices"] = "Falar as opções de diálogo",
    ["Say a dialogue choice to pick it: its words, a part of them, or its number (\"two\", \"the last one\"). If nothing fits clearly, nothing is picked. No character answers.\n\nPresses the arrow keys and Enter, so the game must be in front. Needs speech recognition on this PC. Headphones work best."] = "Diga uma opção de diálogo para escolhê-la: as palavras dela, parte delas ou o número (\"dois\", \"a última\"). Se nada encaixar claramente, nada é escolhido. Nenhum personagem responde.\n\nPressiona as setas do teclado e Enter, então o jogo precisa estar em primeiro plano. Precisa de reconhecimento de voz neste PC. Fones de ouvido funcionam melhor.",
    ["No option matched. Say its number."] = "Nenhuma opção correspondeu. Diga o número dela.",
    ["Two options fit. Say its number."] = "Duas opções combinam. Diga o número dela.",
    ["Speaking a choice needs speech recognition on this PC."] = "Falar uma opção precisa de reconhecimento de voz neste PC.",
    ["AMD’s ROCm PyTorch does not support this card yet."] = "O ROCm PyTorch da AMD ainda não oferece suporte a esta placa.",
    ["Another setup is already running. Wait for it to finish."] = "Outra configuração já está em execução. Aguarde até ela terminar.",
    ["Cancelled"] = "Cancelado",
    ["Cancelling…"] = "Cancelando…",
    ["Checking your card…"] = "Verificando sua placa…",
    ["Downloading {done} of {total} MB ({percent}%)"] = "Baixando {done} de {total} MB ({percent}%)",
    ["Downloading…"] = "Baixando…",
    ["Experimental. Pocket speaks until it is ready. A local voice never switches to a cloud voice."] = "Experimental. O Pocket fala até que esteja pronto. Uma voz local nunca muda para uma voz na nuvem.",
    ["Frees about {disk} GB."] = "Libera cerca de {disk} GB.",
    ["Frees the space it took."] = "Libera o espaço que ocupou.",
    ["Install"] = "Instalar",
    ["Installed"] = "Instalado",
    ["Installed. OmniVoice uses it when it starts."] = "Instalado. O OmniVoice usa quando é iniciado.",
    ["It is kept in the mod’s data folder on drive C:."] = "Ele fica na pasta de dados do mod, na unidade C:.",
    ["It runs in the background while you play. The game keeps running and nothing else changes."] = "Ele roda em segundo plano enquanto você joga. O jogo continua rodando e nada mais muda.",
    ["It takes about {disk} GB on drive C: in the mod’s data folder."] = "Ocupa cerca de {disk} GB na unidade C:, na pasta de dados do mod.",
    ["MIOpen convolutions (AMD)"] = "Convoluções do MIOpen (AMD)",
    ["Not available on this PC. It needs an AMD Radeon card and the OmniVoice pack."] = "Não disponível neste PC. Precisa de uma placa AMD Radeon e do pacote OmniVoice.",
    ["OmniVoice for AMD"] = "OmniVoice para AMD",
    ["OmniVoice on AMD: set up first"] = "OmniVoice na AMD: configure primeiro",
    ["OmniVoice then no longer starts on this card until it is set up again."] = "O OmniVoice então não inicia mais nesta placa até que seja configurado de novo.",
    ["On: AMD’s MIOpen runs the convolutions, with MIOPEN_FIND_MODE=2 and MIOPEN_FIND_ENFORCE=1. Off: PyTorch’s own convolutions. Which is faster depends on your card and driver: if voices are slow or stop part-way, try the other one. AMD cards only. OmniVoice restarts with the new choice when it is idle."] = "Ativado: o MIOpen da AMD executa as convoluções, com MIOPEN_FIND_MODE=2 e MIOPEN_FIND_ENFORCE=1. Desativado: as convoluções próprias do PyTorch. Qual é mais rápida depende da sua placa e do driver: se as vozes ficarem lentas ou pararem no meio, tente a outra. Só para placas AMD. O OmniVoice reinicia com a nova escolha quando estiver ocioso.",
    ["Own Python"] = "Python próprio",
    ["Ready"] = "Pronto",
    ["Ready. OmniVoice runs on {card} with AMD’s ROCm."] = "Pronto. O OmniVoice roda em {card} com o ROCm da AMD.",
    ["Reinstall"] = "Reinstalar",
    ["Remove AMD setup"] = "Remover a configuração da AMD",
    ["Removing the AMD setup…"] = "Removendo a configuração da AMD…",
    ["Run OmniVoice on your AMD Radeon card with AMD’s ROCm: one download, set up from here."] = "Rode o OmniVoice na sua placa AMD Radeon com o ROCm da AMD: um download, configurado daqui.",
    ["Set up OmniVoice for AMD"] = "Configurar OmniVoice para AMD",
    ["Starting the AMD setup…"] = "Iniciando a configuração da AMD…",
    ["Testing it on your card…"] = "Testando na sua placa…",
    ["The AMD setup was removed."] = "A configuração da AMD foi removida.",
    ["The OmniVoice pack is not installed. Install it first."] = "O pacote OmniVoice não está instalado. Instale-o primeiro.",
    ["The conversation service is not running. Restart the game."] = "O serviço de conversa não está em execução. Reinicie o jogo.",
    ["The download did not finish. Check your connection and try again."] = "O download não foi concluído. Verifique sua conexão e tente de novo.",
    ["The download is not ready yet in this version of the mod."] = "O download ainda não está pronto nesta versão do mod.",
    ["The downloaded files did not check out. Try again."] = "Os arquivos baixados não passaram na verificação. Tente de novo.",
    ["The files could not be unpacked. Try again."] = "Não foi possível descompactar os arquivos. Tente de novo.",
    ["The setup did not finish. Try again."] = "A configuração não foi concluída. Tente de novo.",
    ["The setup did not pass the test on your card, so OmniVoice cannot use it."] = "A configuração não passou no teste na sua placa, então o OmniVoice não pode usá-la.",
    ["The setup is installed but did not pass the test on your card. Choose Reinstall."] = "A configuração está instalada, mas não passou no teste na sua placa. Escolha Reinstalar.",
    ["There is not enough free space on drive C:. Free some up and try again."] = "Não há espaço livre suficiente na unidade C:. Libere um pouco e tente de novo.",
    ["This PC has no AMD Radeon card this setup can use."] = "Este PC não tem uma placa AMD Radeon que esta configuração possa usar.",
    ["Unpacking…"] = "Descompactando…",
    ["Your own Python (omni-python.txt) is used instead. Delete that file to use this setup."] = "Seu próprio Python (omni-python.txt) é usado no lugar. Apague esse arquivo para usar esta configuração.",
    ["your AMD card"] = "sua placa AMD",
    ["{voice} · AMD: set up first"] = "{voice} · AMD: configure primeiro",
    ["The AMD setup (Settings > Voices > OmniVoice for AMD) runs OmniVoice with ROCm on {card}. Experimental."] = "A configuração para AMD (Configurações > Vozes > OmniVoice para AMD) roda o OmniVoice com ROCm na {card}. Experimental.",
    ["The AMD setup was not used: {reason}. Choose Reinstall in Settings > Voices > OmniVoice for AMD. Until then Pocket speaks."] = "A configuração para AMD não foi usada: {reason}. Escolha Reinstalar em Configurações > Vozes > OmniVoice para AMD. Até lá, o Pocket fala.",
    ["Borrow eddies from your characters, lend them eddies and pay each other back, by talking. Each character has money of their own, as their story has it, and decides by how they feel about you. Now and then they ask you for a loan.\n\nEddies change hands as soon as a character agrees, and only with your own characters (party, invited visitors, housemates). The game’s own characters only talk about it. Off by default."] = "Peça eddies emprestados aos seus personagens, empreste a eles e paguem de volta conversando. Cada um tem dinheiro próprio e decide pelo que sente por você. Às vezes, eles pedem empréstimo.\n\nEddies mudam de mãos assim que um personagem concorda, e só com os seus próprios personagens (grupo, visitantes, colegas de casa). Os personagens do jogo só falam disso. Desativado por padrão.",
    ["Eddies with characters"] = "Eddies com personagens",
    ["The eddies could not be moved."] = "Não foi possível mover os eddies.",
    ["You do not have enough eddies for that."] = "Você não tem eddies suficientes para isso.",
    ["{name} is no longer with you, so no eddies moved."] = "{name} não está mais com você, então nenhum eddies foi transferido.",
    ["Add to favorites"] = "Adicionar aos favoritos",
    ["One download of about {size} GB."] = "Um download de cerca de {size} GB.",
    ["One download."] = "Um download.",
    ["Remove from favorites"] = "Remover dos favoritos",
    ["Set up OmniVoice on your AMD Radeon card with one download, and choose how it runs."] = "Configure o OmniVoice na sua placa AMD Radeon com um download e escolha como ele roda.",
    ["That entry cannot be a favorite."] = "Essa entrada não pode ser um favorito.",
    ["You have too many favorites. Remove one first."] = "Você tem favoritos demais. Remova um primeiro.",
    ["Your AMD Radeon card ({card}) can run OmniVoice. Set it up in Settings > Voices > OmniVoice for AMD: one download, then it starts by itself."] = "Sua placa AMD Radeon ({card}) pode rodar o OmniVoice. Configure em Configurações > Vozes > OmniVoice para AMD: um download e depois ele inicia sozinho.",
    ["Your favorites could not be saved, so they last only until the game closes."] = "Não foi possível salvar seus favoritos, então eles duram apenas até o jogo fechar.",
    ["{count} matching characters"] = "{count} personagens encontrados",
    ["{name} is no longer a favorite."] = "{name} não é mais um favorito.",
    ["A saved party holds {count} characters, so the rest were left out."] = "Um grupo salvo comporta {count} personagens, então o restante ficou de fora.",
    ["Already with you: {names}."] = "Já estão com você: {names}.",
    ["Another saved party already has that name."] = "Outro grupo salvo já tem esse nome.",
    ["Could not invite: {names}."] = "Não foi possível convidar: {names}.",
    ["Deletes this saved party. The characters in your party now are not touched."] = "Exclui este grupo salvo. Os personagens do seu grupo atual não são afetados.",
    ["Invites the characters of this party to your side: {names}.\n\nIt adds to your party and dismisses nobody. A character who is already with you is not invited twice. Anyone who cannot come is named, with the reason."] = "Convida os personagens deste grupo para o seu lado: {names}.\n\nEles são adicionados ao seu grupo e ninguém é dispensado. Um personagem que já está com você não é convidado duas vezes. Quem não puder vir é citado, com o motivo.",
    ["Parties"] = "Grupos",
    ["Party"] = "Grupo",
    ["Press Delete again to delete {name}."] = "Pressione Excluir de novo para excluir {name}.",
    ["Press again"] = "Pressione de novo",
    ["Press again to delete this saved party. Anything else cancels."] = "Pressione de novo para excluir este grupo salvo. Qualquer outra coisa cancela.",
    ["Rename"] = "Renomear",
    ["Rename party"] = "Renomear grupo",
    ["Renamed to {name}."] = "Renomeado para {name}.",
    ["Replaces the characters of this saved party with the ones in your party now."] = "Substitui os personagens deste grupo salvo pelos que estão no seu grupo agora.",
    ["Save current party"] = "Salvar grupo atual",
    ["Saved as {name}. Press Spawn party under it to invite them again."] = "Salvo como {name}. Pressione Convidar grupo abaixo dele para convidá-los de novo.",
    ["Saved party: {name}"] = "Grupo salvo: {name}",
    ["Saves the characters in your party now, copies and your own characters included, as a party you can invite again with one press. It is named Party 1, Party 2 and so on, and appears below.\n\nYou keep up to {count} saved parties."] = "Salva os personagens que estão agora no seu grupo, incluindo cópias e seus próprios personagens, como um grupo que você pode convidar de novo com um único toque. Ele se chama Grupo 1, Grupo 2 e assim por diante, e aparece abaixo.\n\nVocê pode manter até {count} grupos salvos.",
    ["Spawn"] = "Convidar",
    ["Spawn party"] = "Convidar grupo",
    ["That party no longer exists."] = "Esse grupo não existe mais.",
    ["The characters of this party: {names}."] = "Os personagens deste grupo: {names}.",
    ["The party could not be saved."] = "Não foi possível salvar o grupo.",
    ["This menu has no text box, so the party keeps its name. Mod Configuration Menu has one: type the name in its Search box."] = "Este menu não tem campo de texto, então o grupo mantém o nome. O Mod Configuration Menu tem um: digite o nome no campo de busca dele.",
    ["Type the new name in the Search box at the top (Mod Configuration Menu), then press Rename. Native Settings UI has no text box, so a party keeps its name there."] = "Digite o novo nome no campo de busca do topo (Mod Configuration Menu) e depois pressione Renomear. O Native Settings UI não tem campo de texto, então um grupo mantém o nome ali.",
    ["Type the new name in the Search box first, then press Rename."] = "Primeiro digite o novo nome no campo de busca e depois pressione Renomear.",
    ["Update"] = "Atualizar",
    ["Update with current party"] = "Atualizar com grupo atual",
    ["You can keep {count} saved parties. Delete one first."] = "Você pode manter {count} grupos salvos. Exclua um primeiro.",
    ["Your party is empty. Invite someone first."] = "Seu grupo está vazio. Convide alguém primeiro.",
    ["Your saved parties could not be written to disk, so they last only until the game closes."] = "Seus grupos salvos não puderam ser gravados no disco, então duram só até o jogo fechar.",
    ["that character model is unavailable"] = "o modelo do personagem está indisponível",
    ["the invitation was refused"] = "o convite foi recusado",
    ["{name} ({count})"] = "{name} ({count})",
    ["{name} ({reason})"] = "{name} ({reason})",
    ["{name} deleted."] = "{name} excluído.",
    ["{name} has nobody to invite."] = "{name} não tem ninguém para convidar.",
    ["{name} now has the characters of your party."] = "{name} agora tem os personagens do seu grupo.",
    ["{party}: inviting {names}."] = "{party}: convidando {names}.",
    ["Adds {name} to your favorites. They are listed at the top of page 1, and first in the phone’s Chat tab. Updates never touch them."] = "Adiciona {name} aos favoritos. Eles ficam no topo da página 1 e primeiro na aba Chat do celular. Atualizações nunca os alteram.",
    ["Favorites"] = "Favoritos",
    ["Only the first {count} favorites are listed here. The others are in the list below."] = "Aqui só aparecem os primeiros {count} favoritos. Os outros estão na lista abaixo.",
    ["Page {page} of {pages}: {kind} {first} to {last}."] = "Página {page} de {pages}: {kind} {first} a {last}.",
    ["Press to go to page {page} of {pages}: {kind} {first} to {last}."] = "Pressione para ir à página {page} de {pages}: {kind} {first} a {last}.",
    ["Takes {name} out of your favorites. Her place in the list below stays."] = "Remove {name} dos favoritos. Seu lugar na lista abaixo continua.",
    ["This is the first page."] = "Esta é a primeira página.",
    ["This is the last page."] = "Esta é a última página.",
    ["characters"] = "personagens",
    ["entries"] = "entradas",
    ["models"] = "modelos",
    ["{count} more favorites"] = "Mais {count} favoritos",
    ["{name} is now a favorite. Favorites are at the top of page 1."] = "{name} agora é um favorito. Os favoritos ficam no topo da página 1.",
    ["Favorite"] = "Favorito",
